INSERT INTO `prompt_test_runs` VALUES (4, 40, '{\"ping\":\"pong\",\"task\":\"??????? JSON\"}', '{\n  \"mode\": \"single\",\n  \"steps\": [\n    \"Confirm target account session is active and valid\",\n    \"Navigate to X home compose interface\",\n    \"Insert approved text content into input field\",\n    \"Trigger publish action\",\n    \"Validate final post URL and rendering\"\n  ],\n  \"checks\": [\n    \"Verify account handle matches deployment target\",\n    \"Ensure no duplicate content warning appears\",\n    \"Confirm post visibility in public timeline\",\n    \"Check for any system error notifications\"\n  ],\n  \"notes\": [\n    \"Terminate process if 2FA prompt appears\",\n    \"Retry once if network timeout occurs during upload\",\n    \"Log final post ID for tracking\"\n  ]\n}', NULL, '2026-04-14 21:02:41');
