INSERT INTO `publish_attempts` VALUES (47, 58, 1, 'published', 'https://www.zhihu.com/question/2022414445943486011/answer/2032190684074091932', NULL, NULL, '{\"questionUrl\":\"https://www.zhihu.com/question/2022414445943486011\",\"traceGroupId\":\"job-58-1777291871826-attempt-1\",\"startedAt\":\"2026-04-27T12:11:11.829Z\",\"finishedAt\":\"2026-04-27T12:14:09.911Z\",\"pageSnapshot\":{\"url\":\"https://www.zhihu.com/question/2022414445943486011/answer/2032190684074091932\",\"title\":\"(18 条消息) AI炒股回测年化40%，实盘却亏损20%，问题出在算法还是人性？ - 知乎\",\"visibleTexts\":[\"AI炒股回测年化40%，实盘却亏损20%，问题出在算法还是人性？\",\"把摩擦当常态，用规则锁住人性，别指望算法能替你消化所有波动。交易做久了就知道，赢面不在预测多准，而在策略失效的时候，你能不能靠仓位和纪律把本金捂热，等它自己熬过不适应期。\",\"这挺有意思的，假设你回测90%那你不还是有10%几率亏损么，所以你怎么保证每次不会掉到这10%的区域内\",\"​\",\"消息18\",\"私信\",\"已关注\",\"编辑回答\",\"关注者2\",\"​邀请回答\",\"​好问题\",\"​添加评论\",\"​分享\",\"​赞同\",\"​收藏\",\"​设置\",\"​ 关注\",\"送礼物\",\"​喜欢\",\"申请开通机构号\",\"更多\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"创作中心\",\"股市回测\",\"实盘操作\",\"查看全部 2 个回答\",\"二牛是个老实人\",\"发布于 2026-04-27 20:13\",\"​ 修改\",\"别再撸电子猫了，下一代“电子龙虾”搭子DuMate才是真搭子AI兴趣党的快乐，就是有个能替你熬夜的龙虾级搭子。查看详情AI兴趣党的快乐，就是有个能替你熬夜的龙虾级搭子。 查看详情百度智能云的广告\",\"一分阳光\",\"谢邀 @钱局观察\",\"收录于 · 阳光看世界\",\"发布于 2026-04-02 11:25\",\"回答41\",\"文章0\",\"关注者49\",\"ai这么厉害，用ai炒股可以实现吗？\",\"用AI炒股是一种什么样的体验？\",\"如何利用 AI 在股票市场里赚钱？\",\"如何看待AI炒股？\",\"如何看待Ai炒股？\",\"国家发改委禁止外资收购 Manus 项目597 万\",\"美国白宫记者晚宴发生枪击事件596 万\",\"官方通报女子劝阻男子吸烟引争执366 万\",\"派出所副所长诱骗未成年人吸毒获刑333 万\",\"东方甄选4名主播集体离职306 万\",\"迪士尼游客劝烟被连扇5耳光296 万\",\"DeepSeek V4 预览版上线并开源295 万\",\"南方多省电价突然飙升286 万\",\"25 岁女孩确诊黑色素瘤 5 个月离世277 万\",\"张军272 万\",\"知乎个人信息保护指引\",\"联系我们\",\"涉未成年举报\",\"网络谣言举报\",\"涉企侵权举报\",\"下载知乎\",\"知乎招聘\",\"知乎指南\",\"知乎协议\",\"京ICP证110745号\",\"京ICP备13052560号-1\",\"京公网安备 11010802020088 号\",\"互联网新闻信息服务许可证：11220250001\",\"京网文[2025]0422-132 号\"],\"buttons\":[\"​\",\"消息18\",\"私信\",\"已关注\",\"编辑回答\",\"关注者2\",\"​邀请回答\",\"​好问题\",\"​添加评论\",\"​分享\",\"​赞同\",\"​收藏\",\"​设置\",\"​ 关注\",\"送礼物\",\"​喜欢\",\"申请开通机构号\",\"更多\",\"​ 修改\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\",\"href\":\"https://zhida.zhihu.com/\"},{\"text\":\"创作中心\",\"href\":\"https://www.zhihu.com/creator\"},{\"text\":\"股市回测\",\"href\":\"//www.zhihu.com/topic/23653250\"},{\"text\":\"实盘操作\",\"href\":\"//www.zhihu.com/topic/25785130\"},{\"text\":\"查看全部 2 个回答\",\"href\":\"/question/2022414445943486011\"},{\"text\":\"二牛是个老实人\",\"href\":\"//www.zhihu.com/people/xz33dt\"},{\"text\":\"发布于 2026-04-27 20:13\",\"href\":\"//www.zhihu.com/question/2022414445943486011/answer/2032190684074091932\"},{\"text\":\"别再撸电子猫了，下一代“电子龙虾”搭子DuMate才是真搭子AI兴趣党的快乐，就是有个能替你熬夜的龙虾级搭子。查看详情AI兴趣党的快乐，就是有个能替你熬夜的龙虾级搭子。 查看详情百度智能云的广告\",\"href\":\"https://cloud.baidu.com/product/dumate.html?track=sczhtf&spu=biz%3D0%26ci%3D3711230%26si%3D45f50756-e6a2-46b7-a14f-dc2ac65d35a0%26ts%3D1777292016%26zid%3D1628\"},{\"text\":\"一分阳光\",\"href\":\"//www.zhihu.com/people/yifen-yang-guang\"},{\"text\":\"谢邀 @钱局观察\",\"href\":\"https://www.zhihu.com/people/6320fe64fcee4327739803c1d2bc80df\"},{\"text\":\"收录于 · 阳光看世界\",\"href\":\"https://www.zhihu.com/column/c_1251013215192059904\"},{\"text\":\"发布于 2026-04-02 11:25\",\"href\":\"//www.zhihu.com/question/2022414445943486011/answer/2022998011786052362\"},{\"text\":\"查看全部 2 个回答\",\"href\":\"/question/2022414445943486011\"},{\"text\":\"二牛是个老实人\",\"href\":\"//www.zhihu.com/people/xz33dt\"},{\"text\":\"回答41\",\"href\":\"/people/xz33dt/answers\"},{\"text\":\"文章0\",\"href\":\"/people/xz33dt/posts\"}],\"questionLinks\":[{\"text\":\"查看全部 2 个回答\",\"href\":\"/question/2022414445943486011\"},{\"text\":\"发布于 2026-04-27 20:13\",\"href\":\"//www.zhihu.com/question/2022414445943486011/answer/2032190684074091932\"},{\"text\":\"发布于 2026-04-02 11:25\",\"href\":\"//www.zhihu.com/question/2022414445943486011/answer/2022998011786052362\"},{\"text\":\"查看全部 2 个回答\",\"href\":\"/question/2022414445943486011\"},{\"text\":\"ai这么厉害，用ai炒股可以实现吗？\",\"href\":\"/question/265621650\"},{\"text\":\"用AI炒股是一种什么样的体验？\",\"href\":\"/question/10029727667\"},{\"text\":\"如何利用 AI 在股票市场里赚钱？\",\"href\":\"/question/1947675267721040901\"},{\"text\":\"如何看待AI炒股？\",\"href\":\"/question/2021250859141477528\"},{\"text\":\"如何看待Ai炒股？\",\"href\":\"/question/605725097\"},{\"text\":\"知乎指南\",\"href\":\"/question/19581624\"}],\"editorContent\":null,\"editorContentLength\":0}}', '2026-04-27 20:11:11');
