INSERT INTO `skill_runs` VALUES (283, 12, 12, 'browser-playwright', 'publish_agent', 'login_checking', 'job-12-1774539551330-attempt-2-preflight:skill:snapshot:1774539700237', '{\"action\":\"snapshot\",\"input\":{}}', '{\"url\":\"https://www.zhihu.com/\",\"title\":\"(3 条消息) 首页 - 知乎\",\"visibleTexts\":[\"​\",\"消息3\",\"私信\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 27\",\"​32 条评论\",\"​38\",\"​4\",\"​分享\",\"​赞同 535\",\"​134 条评论\",\"​33\",\"​12\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"创作中心\",\"为什么说股票量化交易比 CTA 更容易赚钱，仅仅因为散户多吗？\",\"为什么现代社会对舞蹈生的负面标签逐渐变深呢？\",\"像哈佛、麻省理工、斯坦福这类的学校的教育水平是否被过誉了？\",\"你逛知乎多久了，如何看待知乎如今的氛围？\",\"币圈给人最大的错觉是什么？\",\"为什么很多人自信地认为中国军力已经断档领先世界了？\",\"Lv4\",\"草稿箱(4)\",\"今日阅读 (播放) 数​396今日新增赞同数​11\",\"进入创作中心​\",\"等你来答​\",\"伊朗局势419 万\",\"张雪峰因心源性猝死去世416 万\",\"南京教师因发表过激言语被停职362 万\",\"OpenAI 关停 AI视频生成平台 Sora316 万\",\"美以袭击伊朗280 万\",\"特朗普称将在5月中旬访华278 万\",\"周杰伦新专辑上线275 万\",\"汽车之家多平台账号被禁止关注266 万\",\"外交部批日本新型军国主义234 万\",\"张雪峰离世当天细节曝光234 万\",\"Undefined\",\"行走在数据边缘\",\"牧羊人\",\"IT 招财胖熊猫\",\"西蒙斯量化\",\"小昕逸逸\",\"广告\",\"我的收藏0\",\"我关注的问题19\",\"我的邀请\",\"我的余额\",\"我的礼券\",\"我的举报\",\"违规诊断\",\"帮助与客服\",\"版权服务中心\",\"知乎个人信息保护指引\",\"联系我们\",\"涉未成年举报\",\"网络谣言举报\",\"涉企侵权举报\",\"下载知乎\",\"知乎招聘\",\"知乎指南\",\"知乎协议\",\"京ICP证110745号\",\"京ICP备13052560号-1\",\"京公网安备 11010802020088 号\",\"互联网新闻信息服务许可证：11220250001\",\"京网文[2025]0422-132 号\",\"药品医疗器械网络信息服务备案（京）网药械信息备字（2022）第00334号\"],\"buttons\":[\"​\",\"消息3\",\"私信\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 27\",\"​32 条评论\",\"​38\",\"​4\",\"​分享\",\"​赞同 535\",\"​134 条评论\",\"​33\",\"​12\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答