INSERT INTO `skill_runs` VALUES (583, 18, 28, 'browser-playwright', 'publish_agent', 'login_checking', 'job-18-1774611718818-attempt-1:skill:snapshot:1774611748791', '{\"action\":\"snapshot\",\"input\":{}}', '{\"url\":\"https://www.zhihu.com/question/2014717415645266005\",\"title\":\"(1 条消息) 币圈2026年还能赚到钱吗？还是只剩机构割韭菜了？ - 知乎\",\"visibleTexts\":[\"币圈2026年还能赚到钱吗？还是只剩机构割韭菜了？\",\"币圈一直都能够赚到钱，别说2026年，2046年同样如此。\",\"加密货币市场体量当下也不差了，有钱的地方，能不能赚到钱，仁者见仁智者见智。\",\"市场一定有人亏钱，有人赚钱，做那一部分赚钱的人。\",\"以我观物，故物我皆著我之色彩，看你怎么看了\",\"长线看币圈还是早期，没出圈，人数少。所以答案是能\",\"Light come from darkness\",\"控制舱位，别想着吃一口大的\",\"​\",\"消息1\",\"私信\",\"关注问题\",\"​写回答\",\"关注者8\",\"​邀请回答\",\"​好问题\",\"​1 条评论\",\"​分享\",\"默认排序\",\"​赞同\",\"​添加评论\",\"​收藏\",\"​喜欢\",\"​赞同 1\",\"收起​\",\"申请开通机构号\",\"更多\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"克币哥\",\"加密货币市场\",\"发布于 2026-03-15 08:53\",\"金融民工\",\"谢邀 @小圆来财\",\"发布于 2026-03-16 16:43\",\"想菜市场自由\",\"发布于 2026-03-11 08:48\",\"世界睡眠日·特别策划丨分享「阿贝贝」赢好礼3.21 世界睡眠日，@答主评审团 邀你聊聊 #我的睡眠阿贝贝。查看详情\",\"Future小哥哥\",\"发布于 2026-03-11 10:00\"],\"buttons\":[\"​\",\"消息1\",\"私信\",\"关注问题\",\"​写回答\",\"关注者8\",\"​邀请回答\",\"​好问题\",\"​1 条评论\",\"​分享\",\"默认排序\",\"​赞同\",\"​添加评论\",\"​收藏\",\"​喜欢\",\"收起​\",\"申请开通机构号\",\"更多\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\",\"href\":\"https://zhida.zhihu.com/\"},{\"text\":\"克币哥\",\"href\":\"//www.zhihu.com/people/caijingkebige\"},{\"text\":\"加密货币市场\",\"href\":\"https://zhida.zhihu.com/search?content_id=773134121&content_type=Answer&match_order=1&q=%E5%8A%A0%E5%AF%86%E8%B4%A7%E5%B8%81%E5%B8%82%E5%9C%BA&zhida_source=entity\"},{\"text\":\"发布于 2