INSERT INTO `skill_runs` VALUES (762, 23, 35, 'browser-playwright', 'publish_agent', 'login_checking', 'job-23-1775140466124-attempt-2-recover-preflight:skill:snapshot:1775140618628', '{\"action\":\"snapshot\",\"input\":{}}', '{\"url\":\"https://www.zhihu.com/\",\"title\":\"(2 封私信 / 23 条消息) 首页 - 知乎\",\"visibleTexts\":[\"个人投资者进行量化交易，有哪些好用的数据源和交易工具推荐？\",\"请问照片里这个人是谁呀？\",\"你是什么时候发现，这个世界其实就是一个巨大的草台班子？\",\"现在和平统一台湾的可能性有多大？\",\"比特皇！从小账户做到1亿7000万后退网，知道他的人应该不多了，他公开过仅有的一些资料，很值得一看！！\",\"有哪些看起来很正经但穿上会很羞耻的衣服？\",\"​\",\"消息23\",\"私信2\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 4\",\"​添加评论\",\"​5\",\"​喜欢\",\"​分享\",\"​赞同 4777\",\"​48 条评论\",\"​900\",\"​134\",\"​赞同 2824\",\"​168 条评论\",\"​404\",\"​176\",\"​赞同 7217\",\"​1844 条评论\",\"​2261\",\"​243\",\"​赞同 43\",\"​10 条评论\",\"​126\",\"​1\",\"​赞同 9663\",\"​327 条评论\",\"​777\",\"​197\",\"​ 关注\",\"申请开通机构号\",\"更多\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"创作中心\"],\"buttons\":[\"​\",\"消息23\",\"私信2\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 4\",\"​添加评论\",\"​5\",\"​喜欢\",\"​分享\",\"​ 关注\",\"申请开通机构号\",\"更多\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\",\"href\":\"https://zhida.zhihu.com/\"},{\"text\":\"创作中心\",\"href\":\"https://www.zhihu.com/creator\"},{\"text\":\"个人投资者进行量化交易，有哪些好用的数据源和交易工具推荐？\",\"href\":\"//www.zhihu.com/question/1955940776333808350/answer/2022378587253163838\"},{\"text\":\"请问照片里这个人是谁呀？\",\"href\":\"//www.zhihu.com/question/322856485/answer/1988194023094100363\"},{\"text\":\"你是什么时候发现，这个世界其实就是一个巨大的草台班子？\",\"href\":\"//www.zhihu.com/question/6544038968/answer/2022341192050909663\"},{\"text\":\"现在和平统一台湾的可能性