INSERT INTO `tool_traces` VALUES (51, 9, 4, 'job-9-1774514184217-attempt-1-preflight:snapshot:1774514186387', 'login_checking', 'playwright', 'snapshot', '{}', '{\"url\":\"https://www.zhihu.com/\",\"title\":\"(9 封私信) 首页 - 知乎\",\"visibleTexts\":[\"​\",\"消息\",\"私信9\",\"发想法\",\"发布\",\"​ 关注\",\"申请开通机构号\",\"更多\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"草稿箱(1)\",\"​开始创作\",\"伊朗局势498 万\",\"张雪峰因心源性猝死去世452 万\",\"中方回应日本自卫队人员闯驻日使馆338 万\",\"OpenAI 关停 AI视频生成平台 Sora320 万\",\"强闯中国驻日使馆男子被捕301 万\",\"张雪峰医疗文件疑遭泄露300 万\",\"周杰伦新专辑上线285 万\",\"南京教师因发表过激言语被停职281 万\",\"张雪峰已为女儿做好未来规划273 万\",\"汽车之家多平台账号被禁止关注254 万\",\"非主流观察\",\"凌志辉\",\"正言看世界\",\"ikaro\",\"涟声微澜\",\"傲慢雨偏剑\",\"张大耳朵\",\"天一论市\",\"豆豆豆豆豆豆豆叶\",\"W的平方\",\"Lyodi\",\"财讯大橘\",\"广告\",\"我的收藏0\",\"我关注的问题0\",\"我的邀请\",\"我的余额\",\"我的礼券\",\"我的举报\",\"违规诊断\",\"帮助与客服\",\"版权服务中心\",\"广告ArkClaw，一键部署OpenClaw，零门槛即刻唤醒个人助手\",\"知乎个人信息保护指引\",\"联系我们\",\"涉未成年举报\",\"网络谣言举报\",\"涉企侵权举报\",\"下载知乎\",\"知乎招聘\",\"知乎指南\",\"知乎协议\",\"京ICP证110745号\",\"京ICP备13052560号-1\",\"京公网安备 11010802020088 号\",\"互联网新闻信息服务许可证：11220250001\",\"京网文[2025]0422-132 号\",\"药品医疗器械网络信息服务备案（京）网药械信息备字（2022）第00334号\",\"广播电视节目制作经营许可证:（京）字第06591号\",\"互联网宗教信息服务许可证：京（2022）0000078\",\"Investor Relations\",\"举报邮箱：jubao@zhihu.com\"],\"buttons\":[\"​\",\"消息\",\"私信9\",\"发想法\",\"发布\",\"​ 关注\",\"申请开通机构号\",\"更多\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\",\"href\":\"https://zhida.zhihu.com/\"},{\"text\":\"草稿箱(1)\",\"href\":\"/draft?type=answer\"},{\"text\":\"​开始创作\",\"href\":\"/question/waiting\"},{\"text\":\"伊朗局势498 万\",\"href\":\"/search?q=%E4%BC%8A%E6%9C%97%E5%B