INSERT INTO `tool_traces` VALUES (324, 18, 28, 'job-18-1774611718818-attempt-1-preflight:snapshot:1774611727531', 'login_checking', 'playwright', 'snapshot', '{}', '{\"url\":\"https://www.zhihu.com/\",\"title\":\"(1 条消息) 首页 - 知乎\",\"visibleTexts\":[\"​\",\"消息1\",\"私信\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 18\",\"​2 条评论\",\"​76\",\"​喜欢\",\"​分享\",\"​赞同 551\",\"​64 条评论\",\"​118\",\"​13\",\"关注\",\"推荐\",\"热榜\",\"专栏\",\"圈子New\",\"付费咨询\",\"知学堂\",\"直答\",\"创作中心\",\"A股散户怎么做量化交易？\",\"张雪峰逝世，年仅 41 岁，因心源性猝死全力抢救无效；郑钦文因为球童递错毛巾要求换回引外网争议；阿里达摩院发布玄铁 C950 刷新 RISC-V 全球性能纪录｜早报 20260325\",\"为什么自然界的数字，1开头的比9开头的多6倍？\",\"币安c2c商家打错钱了，多了1个w，现在联系我我要退给他吗，不退有什么后果?\",\"聪明人为啥也做不好交易？\",\"基于 Rust 的高性能量化因子计算库 py-alpha-lib\",\"Lv4\",\"草稿箱(5)\",\"今日阅读 (播放) 数​215今日新增赞同数​1\",\"进入创作中心​\",\"等你来答​\",\"伊朗局势491 万\",\"南京教师因发表过激言语被停职403 万\",\"张雪峰因心源性猝死去世359 万\",\"黑龙江明确高校逐步消除 8 人间宿舍343 万\",\"罗技短视频组被扣除全部绩效335 万\",\"日本东京发生持刀伤人事件致 2 死327 万\",\"美以袭击伊朗314 万\",\"罗技广告侮辱消费者313 万\",\"为什么速效救心丸可能无法有效急救猝死307 万\",\"OpenAI 关停 AI视频生成平台 Sora301 万\",\"回头太难2012\",\"顾得过来就问一下\",\"霁兴\",\"Tifa Lockhart\",\"至简量化\",\"独狼\",\"徐戈解密\",\"广告\",\"我的收藏0\",\"我关注的问题20\",\"我的邀请\",\"我的余额\",\"我的礼券\",\"我的举报\",\"违规诊断\",\"帮助与客服\",\"版权服务中心\",\"知乎个人信息保护指引\",\"联系我们\",\"涉未成年举报\",\"网络谣言举报\",\"涉企侵权举报\",\"下载知乎\",\"知乎招聘\",\"知乎指南\",\"知乎协议\",\"京ICP证110745号\",\"京ICP备13052560号-1\",\"京公网安备 11010802020088 号\",\"互联网新闻信息服务许可证：11220250001\",\"京网文[2025]0422-132 号\"],\"buttons\":[\"​\",\"消息1\",\"私信\",\"发想法\",\"发布\",\"阅读全文​\",\"​赞同 18\",\"​2 条评论\",\"​76\",\"​喜欢\",\"​分享\",\"​赞同 551\",\"​64 条评论\",\"​118\",\"​13\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\