INSERT INTO `tool_traces` VALUES (374, 22, 30, 'job-22-1775139747794-attempt-2:snapshot:1775140048193', 'publishing', 'playwright', 'snapshot', '{}', '{\"url\":\"https://www.zhihu.com/question/2009444097677628764\",\"title\":\"(2 封私信 / 23 条消息) 加密货币市场近期遭遇集体暴跌，主要原因是什么？ - 知乎\",\"visibleTexts\":[\"加密货币市场近期遭遇集体暴跌，主要原因是什么？\",\"你可以邀请下面用户，快速获得回答\",\"委托刘看山邀请\",\"落日\",\"掩耳盗铃\",\"方展博\",\"月明\",\"识别错别字，提供用词优化建议\",\"自动修正空格、标点及英文大小写\",\"理清全文思路，轻松创作导语\",\"输入你的图片灵感\",\"持续更新中，敬请期待！\",\"加密币上涨的根本原因是疫情阶段为救经济货币超发得厉害 同时又没有正常的行业和产业能够有投资回报 金融机构积累了大量投资人的货币找投资回报率高的合法渠道找不到 而铤而走险进入骗钱的币圈。疫情后经济逐步恢复 也是拉高币值逐步退出的时候了 靠资金量拉高获利退出是这几年的大趋势 暴跌是常态 跌到币价能到大资金的预期价位 才有吸引力 否则就是币圈内骗子群之间狗咬狗的震荡\",\"柬埔寨电诈13w比特币被美国收缴了，作为灰产的资金流通工具，比特币不再安全。\",\"牛市三年，不允许熊市一年吗\",\"​\",\"消息23\",\"私信2\",\"关注问题\",\"​编辑回答\",\"显示全部 ​\",\"关注者2\",\"​邀请回答\",\"​好问题\",\"​添加评论\",\"​分享\",\"​撤销\",\"​重做\",\"​清除格式\",\"​标题\",\"​加粗\",\"​斜体\",\"​列表\",\"​目录\",\"​引用\",\"​分割线\",\"​代码块\",\"​注释\",\"​图片\",\"​视频\",\"​链接\",\"​公式\",\"​表格\",\"​附件\",\"​导入\",\"​草稿备份\",\"​更多\",\"​创作助手\",\"无声明\",\"允许规范转载\",\"任何人都可以评论\",\"​添加来源\",\"发布设置\",\"发布回答\",\"开启邀请\",\"邀请回答\",\"更多推荐结果\",\"默认排序\",\"​ 关注\",\"​赞同 1\",\"​收藏\",\"​喜欢\",\"​赞同\"],\"buttons\":[\"发布回答\",\"​撤销\",\"​重做\",\"​清除格式\",\"​标题\",\"​加粗\",\"​斜体\",\"​列表\",\"​目录\",\"​引用\",\"​分割线\",\"​代码块\",\"​注释\",\"​创作助手\",\"​\",\"无声明\",\"允许规范转载\",\"任何人都可以评论\",\"​添加来源\",\"消息23\",\"私信2\",\"关注问题\",\"​编辑回答\",\"显示全部 ​\",\"关注者2\",\"​邀请回答\",\"​好问题\",\"​添加评论\",\"​分享\",\"​ 关注\",\"​赞同\",\"​收藏\",\"​喜欢\",\"申请开通机构号\",\"更多\",\"换一换\"],\"links\":[{\"text\":\"关注\",\"href\":\"https://www.zhihu.com/follow\"},{\"text\":\"推荐\",\"href\":\"https://www.zhihu.com/\"},{\"text\":\"热榜\",\"href\":\"https://www.zhihu.com/hot\"},{\"text\":\"专栏\",\"href\":\"https://www.zhihu.com/column-square\"},{\"text\":\"圈子New\",\"href\":\"https://www.zhihu.com/ring-feeds\"},{\"text\":\"付费咨询\",\"href\":\"https://www.zhihu.com/consult\"},{\"text\":\"知学堂\",\"href\":\"https://www.zhihu.com/education/learning\"},{\"text\":\"直答\",\"href\":\"https://zhida.zhihu.com/\"},{\"text\":\"创作中