INSERT INTO `topic_candidates` VALUES (51, 1, 'https://www.zhihu.com/question/2020446782954370115', '量化的端到端模型，是个伪命题吗？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T07:22:08.524Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"核心量化策略问题，直击模型有效性痛点，非常适合结合 CryptoPathX 的回测与样本外检验功能进行务实解答。\",\"title\":\"端到端量化模型是伪命题？聊聊策略验证中那些被忽略的坑\",\"summary\":\"探讨端到端模型在交易中的实际局限，强调样本内外检验的重要性。结合个人经验，说明为何可视化回测和交叉验证比单纯迷信模型架构更关键。引导用户关注策略的可验证性而非复杂性。\",\"priority\":\"P1\",\"fit_score\":80,\"question_type\":\"策略构建\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"量化入门者\",\"策略开发者\"],\"pain_points\":[\"模型过拟合\",\"实盘与回测不符\",\"盲目追求复杂模型\"],\"recommended_angle\":\"用实测数据说话，强调验证流程重于模型本身。\",\"persona_hooks\":[\"自己试过各种模型后的结论\",\"回归简单有效的验证逻辑\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"直接对应产品的回测与验证核心功能\",\"must_avoid\":[\"绝对否定某种技术路线\",\"提供具体代码实现\"],\"risk_notes\":[\"避免技术术语堆砌导致难懂\"],\"topic_fingerprint\":{\"problem_core\":\"量化模型有效性\",\"answer_angle\":\"技术务实分析\",\"target_pain\":\"策略实盘失效\",\"promo_entry\":\"多周期交叉验证与回测\"}},\"prefilterCachedAt\":\"2026-03-26T07:24:03.707Z\"}', 'P1', 80, '策略构建', '二牛实测型', '[\"绝对否定某种技术路线\",\"提供具体代码实现\"]', '[\"避免技术术语堆砌导致难懂\"]', 'valid', '核心量化策略问题，直击模型有效性痛点，非常适合结合 CryptoPathX 的回测与样本外检验功能进行务实解答。', '2026-03-26 15:24:03', 'blocked', '已经重写 1 次，仍未通过审核。', '2026-03-26 15:22:08');
