INSERT INTO `topic_candidates` VALUES (57, 1, 'https://www.zhihu.com/question/399120086', '作为刚入币圈的人，你需要注意些什么？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T07:24:05.878Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T07:24:05.883Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"高风险意识类问题，与产品风险管理能力高度契合。用户关注\'注意什么\'，正是植入风控理念和验证工具的好机会。\",\"title\":\"刚入币圈需要注意些什么？老实话：保住本金比赚钱更重要\",\"summary\":\"针对新手的生存指南。重点讨论资金安全、防骗意识、情绪管理和仓位控制。强调不要杠杆，不要借贷，用历史数据辅助判断而非听消息。\",\"priority\":\"P1\",\"fit_score\":88,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"刚入金的新手\",\"有过小额亏损经历的用户\"],\"pain_points\":[\"怕资金不安全\",\"怕操作失误\",\"不知道风险在哪\"],\"recommended_angle\":\"以\'生存\'为核心，列举具体风险场景，并给出应对策略（如复盘、验证）。\",\"persona_hooks\":[\"分享自己早期忽视风险的经历\",\"强调老实做人，踏实做事\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在提到\'复盘\'和\'验证历史走势\'时，可轻描淡写提及工具辅助。\",\"must_avoid\":[\"推荐实盘平台\",\"鼓励高频交易\",\"夸大风险可控性\"],\"risk_notes\":[\"合规风险，避免指导具体操作\",\"避免引发焦虑\"],\"topic_fingerprint\":{\"problem_core\":\"新手生存风险\",\"answer_angle\":\"风控第一，交易第二\",\"target_pain\":\"本金损失\",\"promo_entry\":\"复盘与风险验证工具\"}},\"prefilterCachedAt\":\"2026-03-26T07:25:49.405Z\"}', 'P1', 88, '风险管理', '二牛踩坑型', '[\"推荐实盘平台\",\"鼓励高频交易\",\"夸大风险可控性\"]', '[\"合规风险，避免指导具体操作\",\"避免引发焦虑\"]', 'valid', '高风险意识类问题，与产品风险管理能力高度契合。用户关注\'注意什么\'，正是植入风控理念和验证工具的好机会。', '2026-03-26 15:25:49', 'blocked', '已经重写 1 次，仍未通过审核。', '2026-03-26 15:24:05');
