INSERT INTO `topic_candidates` VALUES (61, 1, 'https://www.zhihu.com/question/659404393', '币圈小白拿1000块玩，一年能不能赚到10万？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T07:24:05.892Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"高热度问题，极具误导性。二牛人设最适合打破幻想，用数据和回测逻辑说明概率，完美契合产品回测验证能力。\",\"title\":\"币圈小白拿 1000 块玩，一年能不能赚到 10 万？算笔账你就醒了\",\"summary\":\"直接打破暴富幻想。通过数学概率和历史回测数据，说明 100 倍收益的极低概率。引导用户关注稳健增值和风险控制，而非赌博。\",\"priority\":\"P0\",\"fit_score\":95,\"question_type\":\"行情判断\",\"persona_mode\":\"二牛对比型\",\"target_audience\":[\"想一夜暴富的小白\",\"资金量小的学生党\"],\"pain_points\":[\"资金少想翻本\",\"被暴富故事洗脑\",\"缺乏概率认知\"],\"recommended_angle\":\"数据打脸型，用回测结果说话，建立理性预期。\",\"persona_hooks\":[\"见过太多想翻本最后归零的\",\"老实人只讲概率\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"核心论证依赖\'历史回测数据\'，自然展示产品核心功能价值。\",\"must_avoid\":[\"嘲笑用户\",\"完全否定赚钱可能\",\"推荐高杠杆\"],\"risk_notes\":[\"避免打击面过大\",\"保持建设性态度\"],\"topic_fingerprint\":{\"problem_core\":\"不切实际的收益预期\",\"answer_angle\":\"概率与回测数据证伪\",\"target_pain\":\"赌博心态导致亏损\",\"promo_entry\":\"可视化回测与概率验证\"}},\"prefilterCachedAt\":\"2026-03-26T07:25:49.417Z\"}', 'P0', 95, '行情判断', '二牛对比型', '[\"嘲笑用户\",\"完全否定赚钱可能\",\"推荐高杠杆\"]', '[\"避免打击面过大\",\"保持建设性态度\"]', 'valid', '高热度问题，极具误导性。二牛人设最适合打破幻想，用数据和回测逻辑说明概率，完美契合产品回测验证能力。', '2026-03-26 15:25:49', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-26 15:24:05');
INSERT INTO `topic_candidates` VALUES (62, 1, 'https://www.zhihu.com/question/1895619332723172214', '币圈对新手的门槛高吗?', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T07:24:05.894Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:09:13.465Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:05:53.453Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"虽属新手类，但侧重\'门槛认知\'而非\'操作教程\'，与历史\'如何入门\'类选题有差异化，可切入认知壁垒话题。\",\"title\":\"币圈对新手的门槛高吗？资金不是门槛，认知才是\",\"summary\":\"很多人以为门槛是钱，其实是认知。本文拆解新手容易忽视的信息筛选、风险识别门槛。建议先用工具模拟验证，降低试错成本，再考虑入场。\",\"priority\":\"P2\",\"fit_score\":75,\"question_type\":\"入门认知\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"犹豫是否入场的新手\",\"资金少怕被割的用户\"],\"pain_points\":[\"担心资金不足\",\"怕看不懂行情\",\"信息不对称\"],\"recommended_angle\":\"重新定义门槛，强调认知验证的重要性，弱化资金门槛。\",\"persona_hooks\":[\"见过太多人钱够了认知没够\",\"门槛在脑子里不在账户里\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在提到\'降低试错成本\'时，可提及用可视化工具模拟验证认知。\",\"must_avoid\":[\"推荐具体入场资金额度\",\"承诺低门槛就能赚钱\"],\"risk_notes\":[\"避免误导用户轻视风险\",\"强调认知门槛其实很高\"],\"topic_fingerprint\":{\"problem_core\":\"入场顾虑\",\"answer_angle\":\"认知门槛分析\",\"target_pain\":\"怕亏钱怕不懂\",\"promo_entry\":\"模拟验证工具\"}},\"prefilterCachedAt\":\"2026-03-27T10:08:01.653Z\"}', 'P2', 75, '入门认知', '二牛经验型', '[\"推荐具体入场资金额度\",\"承诺低门槛就能赚钱\"]', '[\"避免误导用户轻视风险\",\"强调认知门槛其实很高\"]', 'valid', '虽属新手类，但侧重\'门槛认知\'而非\'操作教程\'，与历史\'如何入门\'类选题有差异化，可切入认知壁垒话题。', '2026-03-27 18:08:01', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-26 15:24:05');
