INSERT INTO `topic_candidates` VALUES (91, 2, 'https://www.zhihu.com/question/1934317826811880155', '有没有大佬预言一下未来5-10年的风口?', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T10:10:07.678Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"风口预测类问题，可转化为\'如何验证趋势\'的方法论。符合焦花花理性分析人设，能自然引入量化思维和历史回测验证，避免空谈预测。\",\"title\":\"未来 5-10 年的风口在哪？比起预测，我更相信这套验证逻辑\",\"summary\":\"没人能准确预言风口，但可以通过数据验证趋势的持续性。不谈具体币种，只谈如何识别真趋势与假热点。结合量化思维，用历史回测看哪些赛道穿越了周期。适合想长期布局而非短线投机的人。\",\"priority\":\"P1\",\"fit_score\":80,\"question_type\":\"入门认知\",\"persona_mode\":\"焦花花实测型\",\"target_audience\":[\"长期投资者\",\"趋势交易者\",\"理性分析派\"],\"pain_points\":[\"怕跟错风口\",\"缺乏验证手段\",\"容易被消息误导\"],\"recommended_angle\":\"否定盲目预测，提倡数据验证，展示如何用工具测试赛道生命力。\",\"persona_hooks\":[\"不做大预言家\",\"只讲验证逻辑\",\"展示回测思路\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为方法论的一部分提及工具验证，不强行推销。\",\"must_avoid\":[\"具体年份预测\",\"保证某个赛道必涨\",\"夸大产品预测能力\"],\"risk_notes\":[\"避免涉及宏观政治敏感\",\"保持客观中立\"],\"topic_fingerprint\":{\"problem_core\":\"趋势不确定性\",\"answer_angle\":\"验证优于预测\",\"target_pain\":\"怕选错赛道\",\"promo_entry\":\"策略回测验证\"}},\"prefilterCachedAt\":\"2026-03-26T10:11:30.056Z\"}', 'P1', 80, '入门认知', '焦花花实测型', '[\"具体年份预测\",\"保证某个赛道必涨\",\"夸大产品预测能力\"]', '[\"避免涉及宏观政治敏感\",\"保持客观中立\"]', 'valid', '风口预测类问题，可转化为\'如何验证趋势\'的方法论。符合焦花花理性分析人设，能自然引入量化思维和历史回测验证，避免空谈预测。', '2026-03-26 18:11:30', 'blocked', '已经重写 1 次，仍未通过审核。', '2026-03-26 18:10:07');
