INSERT INTO `topic_candidates` VALUES (99, 2, 'https://www.zhihu.com/question/4606985456', '加密货币市场的未来潜力还有多大？', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-26T11:06:44.772Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"属于币圈市场认知类，符合产品逻辑中的行情判断与历史走势对比能力。焦花花可用数据周期视角回答，避免情绪化预测，自然植入工具的历史验证功能。\",\"title\":\"加密货币市场的未来潜力还有多大？别只听故事，看数据周期\",\"summary\":\"市场潜力话题容易陷入情绪化吹捧。焦花花应从历史周期数据入手，分析牛熊转换规律，而非预测具体点位。强调用数据验证市场阶段，避免盲目信仰。适合建立理性认知，自然引入工具的历史走势对比功能，帮助用户判断当前所处周期位置，而非单纯喊单。\",\"priority\":\"P1\",\"fit_score\":80,\"question_type\":\"行情判断\",\"persona_mode\":\"焦花花经验型\",\"target_audience\":[\"持仓用户\",\"观望投资者\",\"周期研究者\"],\"pain_points\":[\"不知道当前市场阶段\",\"容易被消息面误导\",\"缺乏历史数据参考\"],\"recommended_angle\":\"用历史周期数据拆解当前市场位置，强调验证而非预测\",\"persona_hooks\":[\"数据驱动决策\",\"不盲目看多或看空\",\"理性分析周期\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为判断周期的辅助工具提及，强调数据验证的重要性，不强行推销。\",\"must_avoid\":[\"具体点位预测\",\"保证收益\",\"煽动情绪\"],\"risk_notes\":[\"避免被视为投资建议\",\"数据需准确\"],\"topic_fingerprint\":{\"problem_core\":\"市场周期认知\",\"answer_angle\":\"历史数据对比 + 周期分析\",\"target_pain\":\"迷茫于市场阶段\",\"promo_entry\":\"历史走势对比工具\"}},\"prefilterCachedAt\":\"2026-03-26T11:08:44.494Z\"}', 'P1', 80, '行情判断', '焦花花经验型', '[\"具体点位预测\",\"保证收益\",\"煽动情绪\"]', '[\"避免被视为投资建议\",\"数据需准确\"]', 'valid', '属于币圈市场认知类，符合产品逻辑中的行情判断与历史走势对比能力。焦花花可用数据周期视角回答，避免情绪化预测，自然植入工具的历史验证功能。', '2026-03-26 19:08:44', 'published', '{\"problem_core\":\"市场周期认知\",\"answer_angle\":\"历史数据对比 + 周期分析\",\"target_pain\":\"迷茫于市场阶段\",\"promo_entry\":\"历史走势对比工具\"}', '2026-03-26 19:06:44');
