INSERT INTO `topic_candidates` VALUES (122, 2, 'https://www.zhihu.com/question/659185503', '你们进入币圈是自己摸索还是跟专业老师带呢?', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:29:35.155Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"直击新手痛点（跟单风险 vs 自学难度），契合产品\'独立验证\'的核心价值。焦花花人设适合分享从依赖他人到建立自己体系的转变，自然引出工具辅助决策的必要性，属于交易认知类优质选题。\",\"title\":\"币圈是自学成才还是跟老师？我的血泪教训告诉你真相\",\"summary\":\"很多新人迷信“老师带单”，结果成为接盘侠。焦花花分享自己从跟单亏损到独立交易的转变，强调建立自己验证体系的重要性。不否定学习，但强调验证。自然引入工具作为验证手段，帮助用户建立独立判断能力，避免盲目依赖。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"入门认知\",\"persona_mode\":\"焦花花踩坑型\",\"target_audience\":[\"币圈新手\",\"跟单亏损者\",\"犹豫是否报班的人\"],\"pain_points\":[\"怕被老师割韭菜\",\"自学无从下手\",\"缺乏独立判断能力\"],\"recommended_angle\":\"对比跟单与自学的利弊，核心落脚在\'验证\'而非\'听信\'，引出工具作为验证伙伴。\",\"persona_hooks\":[\"曾迷信老师导致亏损\",\"现在只信数据验证\",\"不卖课只分享经验\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品作为\'独立验证工具\'出现，解决\'无法判断老师对错\'的痛点，逻辑顺畅。\",\"must_avoid\":[\"推荐具体老师或社群\",\"完全否定学习他人\",\"承诺自学一定能赚\"],\"risk_notes\":[\"避免涉及具体带单群曝光\",\"保持客观中立\"],\"topic_fingerprint\":{\"problem_core\":\"学习路径依赖\",\"answer_angle\":\"独立验证能力培养\",\"target_pain\":\"害怕被误导\",\"promo_entry\":\"用工具验证策略有效性\"}},\"prefilterCachedAt\":\"2026-03-27T08:31:28.703Z\"}', 'P1', 85, '入门认知', '焦花花踩坑型', '[\"推荐具体老师或社群\",\"完全否定学习他人\",\"承诺自学一定能赚\"]', '[\"避免涉及具体带单群曝光\",\"保持客观中立\"]', 'valid', '直击新手痛点（跟单风险 vs 自学难度），契合产品\'独立验证\'的核心价值。焦花花人设适合分享从依赖他人到建立自己体系的转变，自然引出工具辅助决策的必要性，属于交易认知类优质选题。', '2026-03-27 16:31:28', 'blocked', '已经重写 1 次，仍未通过审核。', '2026-03-27 16:29:35');
