INSERT INTO `topic_candidates` VALUES (127, 2, 'https://www.zhihu.com/question/12094429635', '在币圈能否挣到钱？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:31:31.606Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:13:52.597Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:12:52.398Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:25:53.872Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"币圈核心认知题，但与本批次候选 96 高度相似。96 题（翻身）情绪痛点更强，本题（挣钱）较泛。保留为备选，优先级低于 96。\",\"title\":\"在币圈能否挣到钱？别听故事，看概率与周期\",\"summary\":\"不直接回答能或不能，而是拆解赚钱的群体特征。结合历史周期数据，说明赚钱需要认知变现而非运气。引导用户用工具验证历史走势，建立理性预期，避免盲目入场。\",\"priority\":\"P2\",\"fit_score\":75,\"question_type\":\"行情判断\",\"persona_mode\":\"焦花花经验型\",\"target_audience\":[\"观望投资者\",\"亏损用户\",\"周期研究者\"],\"pain_points\":[\"不确定市场是否还有机会\",\"容易被暴富故事误导\",\"缺乏客观数据支撑\"],\"recommended_angle\":\"用历史数据拆解赚钱概率，强调认知而非运气\",\"persona_hooks\":[\"不吹牛只讲概率\",\"数据驱动决策\",\"理性看待收益\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为验证市场周期的辅助工具提及，不强行推销。\",\"must_avoid\":[\"保证收益\",\"推荐具体币种\",\"煽动情绪\"],\"risk_notes\":[\"避免被视为投资建议\",\"数据需准确\"],\"topic_fingerprint\":{\"problem_core\":\"赚钱可能性认知\",\"answer_angle\":\"概率分析 + 历史数据\",\"target_pain\":\"迷茫于市场机会\",\"promo_entry\":\"历史走势对比工具\"}},\"prefilterCachedAt\":\"2026-03-27T11:29:21.443Z\"}', 'P2', 75, '行情判断', '焦花花经验型', '[\"保证收益\",\"推荐具体币种\",\"煽动情绪\"]', '[\"避免被视为投资建议\",\"数据需准确\"]', 'valid', '币圈核心认知题，但与本批次候选 96 高度相似。96 题（翻身）情绪痛点更强，本题（挣钱）较泛。保留为备选，优先级低于 96。', '2026-03-27 19:29:21', 'blocked', '与候选 96 核心意图高度重合。96 题的‘普通人翻身’痛点更具体、情绪张力更强，优先保留 96。127 题过于宽泛，容易写成泛泛而谈的鸡汤，难以体现焦花花的务实人设和产品验证价值。', '2026-03-27 16:31:31');
INSERT INTO `topic_candidates` VALUES (128, 2, 'https://www.zhihu.com/question/1933180014964246033', '币圈合约到底能不能赚钱？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:31:31.608Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:13:52.599Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:12:52.400Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:25:53.875Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"合约是高痛点高风险话题。焦花花人设需强调风险而非鼓励杠杆。适合引入风险管理和策略验证能力，警示用户。\",\"title\":\"币圈合约到底能不能赚钱？先算算爆仓风险再下手\",\"summary\":\"直面合约高风险本质。不鼓励杠杆，而是分析为何大多数人亏损。强调止损纪律和策略回测的重要性。适合用工具模拟历史极端行情，展示风险控制的核心价值。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"风险管理\",\"persona_mode\":\"焦花花踩坑型\",\"target_audience\":[\"合约交易者\",\"高风险偏好者\",\"亏损用户\"],\"pain_points\":[\"频繁爆仓\",\"无法控制仓位\",\"缺乏风控策略\"],\"recommended_angle\":\"风险警示 + 风控纪律，引入回测验证策略存活率\",\"persona_hooks\":[\"真金白银换来的教训\",\"不回避亏损经历\",\"强调生存第一\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品回测功能可直接展示极端行情下的策略表现，契合风控主题。\",\"must_avoid\":[\"鼓励高杠杆\",\"推荐交易所\",\"保证不亏\"],\"risk_notes\":[\"高合规风险\",\"避免诱导交易\",\"强调风险自负\"],\"topic_fingerprint\":{\"problem_core\":\"合约风险与收益\",\"answer_angle\":\"风控纪律 + 策略验证\",\"target_pain\":\"害怕爆仓和亏损\",\"promo_entry\":\"策略回测与风险模拟\"}},\"prefilterCachedAt\":\"2026-03-27T11:29:21.447Z\"}', 'P1', 85, '风险管理', '焦花花踩坑型', '[\"鼓励高杠杆\",\"推荐交易所\",\"保证不亏\"]', '[\"高合规风险\",\"避免诱导交易\",\"强调风险自负\"]', 'valid', '合约是高痛点高风险话题。焦花花人设需强调风险而非鼓励杠杆。适合引入风险管理和策略验证能力，警示用户。', '2026-03-27 19:29:21', 'blocked_duplicate', '核心叙事逻辑与已发布题目“你人生中太晚明白的道理是什么？”高度重合（踩坑经历 + 工具避免损失），且与“小白如何避免踩坑”在风控切入点上过于相似，缺乏新意。', '2026-03-27 16:31:31');
