INSERT INTO `topic_candidates` VALUES (130, 2, 'https://www.zhihu.com/question/1927743175210039243', '币圈带单老师靠谱吗？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:31:31.612Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:13:52.604Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:12:52.406Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:25:53.881Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"极高痛点。带单老师是币圈常见骗局/误区。焦花花人设适合揭露真相，强调独立验证。产品回测功能可直接用于验证老师战绩真实性。\",\"title\":\"币圈带单老师靠谱吗？别让你的本金为别人的演技买单\",\"summary\":\"揭露带单常见套路。强调不要盲目跟单，要用数据验证过往战绩。引导用户使用工具自行回测策略，建立独立判断能力。适合建立信任感，体现负责任态度。\",\"priority\":\"P0\",\"fit_score\":95,\"question_type\":\"风险管理\",\"persona_mode\":\"焦花花实测型\",\"target_audience\":[\"跟单亏损者\",\"新手\",\"怀疑论者\"],\"pain_points\":[\"被带单亏损\",\"无法验证老师实力\",\"缺乏独立判断\"],\"recommended_angle\":\"揭露套路 + 数据验证，强调独立交易能力\",\"persona_hooks\":[\"敢于说真话\",\"用数据打假\",\"保护用户本金\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品核心能力（回测验证）直接解决“如何验证老师战绩”的问题，植入逻辑极顺。\",\"must_avoid\":[\"点名攻击具体老师\",\"法律建议\",\"绝对化结论\"],\"risk_notes\":[\"避免诽谤风险\",\"聚焦方法论而非个案\"],\"topic_fingerprint\":{\"problem_core\":\"信任与验证\",\"answer_angle\":\"数据验证 + 独立判断\",\"target_pain\":\"怕被骗和亏损\",\"promo_entry\":\"策略回测与战绩验证\"}},\"prefilterCachedAt\":\"2026-03-27T11:29:21.457Z\"}', 'P0', 95, '风险管理', '焦花花实测型', '[\"点名攻击具体老师\",\"法律建议\",\"绝对化结论\"]', '[\"避免诽谤风险\",\"聚焦方法论而非个案\"]', 'valid', '极高痛点。带单老师是币圈常见骗局/误区。焦花花人设适合揭露真相，强调独立验证。产品回测功能可直接用于验证老师战绩真实性。', '2026-03-27 19:29:21', 'blocked', '已经重写 1 次，仍未通过审核。', '20