INSERT INTO `topic_candidates` VALUES (131, 2, 'https://www.zhihu.com/question/666689620', '你在币圈赚了多少钱了？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:31:31.615Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:13:52.606Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:12:52.410Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:25:53.886Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"invalid\",\"validity_reason\":\"合规高风险。晒收益易被误解为诱导投资或炫耀，违反“不保证赚钱”原则。难以在不违规的前提下真实回答。\",\"title\":\"你在币圈赚了多少钱了？\",\"summary\":\"跳过。涉及具体收益金额，易引发合规风险及用户误解。焦花花人设应侧重方法论而非收益炫耀，避免陷入晒单陷阱。\",\"priority\":\"SKIP\",\"fit_score\":0,\"question_type\":\"其他\",\"persona_mode\":\"焦花花经验型\",\"target_audience\":[\"围观群众\"],\"pain_points\":[\"好奇他人收益\"],\"recommended_angle\":\"不建议回答\",\"persona_hooks\":[],\"soft_promo_mode\":\"none\",\"soft_promo_reason\":\"易引发合规风险\",\"must_avoid\":[\"具体金额\",\"收益截图\",\"诱导交易\"],\"risk_notes\":[\"高合规风险\",\"易被判定为营销号\"],\"topic_fingerprint\":{\"problem_core\":\"收益炫耀\",\"answer_angle\":\"无\",\"target_pain\":\"无\",\"promo_entry\":\"none\"}},\"prefilterCachedAt\":\"2026-03-27T11:29:21.460Z\"}', 'SKIP', 0, '其他', '焦花花经验型', '[\"具体金额\",\"收益截图\",\"诱导交易\"]', '[\"高合规风险\",\"易被判定为营销号\"]', 'invalid', '合规高风险。晒收益易被误解为诱导投资或炫耀，违反“不保证赚钱”原则。难以在不违规的前提下真实回答。', '2026-03-27 19:29:21', 'blocked', '合规高风险。晒收益易被误解为诱导投资或炫耀，违反“不保证赚钱”原则。难以在不违规的前提下真实回答。', '2026-03-27 16:31:31');
