INSERT INTO `topic_candidates` VALUES (133, 2, 'https://www.zhihu.com/question/2020097181915324603', '进入信贷风控领域，需具备哪些核心技能？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:31:31.619Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:13:52.610Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:12:52.414Z\"},{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:25:53.891Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"invalid\",\"validity_reason\":\"领域不符。信贷风控属于传统金融就业技能，与币圈交易量化无直接关联。无法体现产品价值。\",\"title\":\"进入信贷风控领域，需具备哪些核心技能？\",\"summary\":\"跳过。属于传统金融职业规划，与 CryptoPathX 的币圈量化交易定位不符。受众重叠度低，无法自然植入。\",\"priority\":\"SKIP\",\"fit_score\":0,\"question_type\":\"其他\",\"persona_mode\":\"焦花花经验型\",\"target_audience\":[\"求职者\",\"传统金融从业者\"],\"pain_points\":[\"职业技能缺失\"],\"recommended_angle\":\"不建议回答\",\"persona_hooks\":[],\"soft_promo_mode\":\"none\",\"soft_promo_reason\":\"领域不符\",\"must_avoid\":[\"强行关联\"],\"risk_notes\":[\"内容不相关\"],\"topic_fingerprint\":{\"problem_core\":\"职业技能\",\"answer_angle\":\"无\",\"target_pain\":\"无\",\"promo_entry\":\"none\"}},\"prefilterCachedAt\":\"2026-03-27T11:29:21.470Z\"}', 'SKIP', 0, '其他', '焦花花经验型', '[\"强行关联\"]', '[\"内容不相关\"]', 'invalid', '领域不符。信贷风控属于传统金融就业技能，与币圈交易量化无直接关联。无法体现产品价值。', '2026-03-27 19:29:21', 'blocked', '领域不符。信贷风控属于传统金融就业技能，与币圈交易量化无直接关联。无法体现产品价值。', '2026-03-27 16:31:31');
INSERT INTO `topic_candidates` VALUES (134, 2, 'https://www.zhihu.com/question/1957269503563011513', '小白进入币圈一个月，跟着别人做，已经亏了7w，该怎么办？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:34:02.426Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:34:02.439Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:16:23.999Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:16:24.015Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:15:16.291Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:15:16.307Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:29:23.822Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"痛点极清晰（已亏损 7w），情绪强烈，急需风险管理和止损建议。天然契合产品的策略验证和回测能力，可用来拆解跟单失败原因，强调独立验证的重要性。\",\"title\":\"币圈小白一月亏 7w？先停手，做好这 3 步再谈回本\",\"summary\":\"亏损后最忌冲动回本。焦花花建议先停止交易，复盘跟单逻辑为何失效。强调独立验证策略的重要性，利用历史数据回测看清所谓“老师”策略的真实胜率。建立止损纪律，避免本金归零。适合急需止损反思的亏损用户，自然引入工具的策略验证功能，帮助识别靠谱策略。\",\"priority\":\"P0\",\"fit_score\":90,\"question_type\":\"风险管理\",\"persona_mode\":\"焦花花踩坑型\",\"target_audience\":[\"已亏损新手\",\"跟单受害者\",\"冲动交易者\"],\"pain_points\":[\"急于回本导致更大亏损\",\"盲目信任他人策略\",\"缺乏止损纪律\"],\"recommended_angle\":\"情绪安抚 + 止损纪律 + 策略验证方法论\",\"persona_hooks\":[\"见过太多类似案例\",\"不鼓励盲目回本\",\"强调独立验证\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品回测功能直接用于验证跟单策略的有效性，解决“为什么亏”的核心疑问，植入逻辑顺畅。\",\"must_avoid\":[\"推荐具体回本方案\",\"承诺追回损失\",\"推荐具体交易所\"],\"risk_notes\":[\"避免被视为投资建议\",\"注意用户情绪脆弱，措辞需温和坚定\"],\"topic_fingerprint\":{\"problem_core\":\"亏损后的心理与策略重建\",\"answer_angle\":\"止损纪律 + 策略独立验证\",\"target_pain\":\"害怕继续亏损且不知为何亏\",\"promo_entry\":\"用工具回测验证跟单策略历史表现\"}},\"prefilterCachedAt\":\"2026-03-27T11:31:17.798Z\"}', 'P0', 90, '风险管理', '焦花花踩坑型', '[\"推荐具体回本方案\",\"承诺追回损失\",\"推荐具体交易所\"]', '[\"避免被视为投资建议\",\"注意用户情绪脆弱，措辞需温和坚定\"]', 'valid', '痛点极清晰（已亏损 7w），情绪强烈，急需风险管理和止损建议。天然契合产品的策略验证和回测能力，可用来拆解跟单失败原因，强调独立验证的重要性。', '2026-03-27 19:31:17', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-27 16:34:02');
INSERT INTO `topic_candidates` VALUES (135, 2, 'https://www.zhihu.com/question/1977833775028273316', '新手小白怎么了解币圈?', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:34:02.431Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:16:24.007Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:15:16.298Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"学习路径类问题，与 86 类似但更侧重渠道和方法。可涵盖信息筛选能力，自然带入“如何验证信息真伪”的产品价值。\",\"title\":\"新手小白怎么了解币圈？别只看新闻，要看数据\",\"summary\":\"梳理靠谱的信息获取渠道，强调数据优于消息。焦花花建议新手从链上数据、历史走势入手，而非社交媒体情绪。可介绍如何利用工具过滤噪音，建立自己的信息分析框架，避免被误导。\",\"priority\":\"P2\",\"fit_score\":70,\"question_type\":\"入门认知\",\"persona_mode\":\"焦花花实测型\",\"target_audience\":[\"信息过载新手\",\"自学型用户\",\"研究爱好者\"],\"pain_points\":[\"信息杂乱\",\"真假难辨\",\"不知道信谁\"],\"recommended_angle\":\"信息筛选方法论 + 数据验证\",\"persona_hooks\":[\"分享自用信息源\",\"强调独立核实\",\"拒绝噪音\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为获取和验证数据的渠道之一提及，强调数据源的重要性。\",\"must_avoid\":[\"推荐具体媒体\",\"贬低其他平台\",\"过度技术化\"],\"risk_notes\":[\"信息准确性免责\",\"避免广告嫌疑\"],\"topic_fingerprint\":{\"problem_core\":\"信息获取与筛选\",\"answer_angle\":\"数据驱动的信息流\",\"target_pain\":\"信息焦虑\",\"promo_entry\":\"数据查询与验证\"}},\"prefilterCachedAt\":\"2026-03-27T10:17:29.570Z\"}', 'P2', 70, '入门认知', '焦花花实测型', '[\"推荐具体媒体\",\"贬低其他平台\",\"过度技术化\"]', '[\"信息准确性免责\",\"避免广告嫌疑\"]', 'valid', '学习路径类问题，与 86 类似但更侧重渠道和方法。可涵盖信息筛选能力，自然带入“如何验证信息真伪”的产品价值。', '2026-03-27 18:17:29', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-27 16:34:02');
INSERT INTO `topic_candidates` VALUES (136, 2, 'https://www.zhihu.com/question/1895619332723172214', '币圈对新手的门槛高吗?', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T08:34:02.434Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:16:24.010Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:15:16.300Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:29:23.853Z\"},{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"币圈新手\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T11:29:23.858Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"认知类问题，适合做风险警示。可区分“技术门槛”与“认知门槛”，强调生存难度。契合产品历史走势对比功能，展示市场波动风险。\",\"title\":\"币圈新手门槛高吗？技术不高，但“认知税”很贵\",\"summary\":\"门槛不在技术，而在风险认知。焦花花指出新手易忽视波动风险，把运气当实力。建议用历史数据回测体验极端行情，理解生存难度。适合观望人群，降低盲目入场预期。轻量提及工具的历史走势对比功能，帮助用户客观评估自身承受能力，而非劝退或煽动。\",\"priority\":\"P2\",\"fit_score\":80,\"question_type\":\"行情判断\",\"persona_mode\":\"焦花花实测型\",\"target_audience\":[\"观望投资者\",\"风险敏感型用户\",\"职场稳定人群\"],\"pain_points\":[\"怕入场即被套\",\"不清楚市场风险程度\",\"高估自己承受能力\"],\"recommended_angle\":\"风险认知教育 + 历史数据警示\",\"persona_hooks\":[\"强调生存不易\",\"不美化市场\",\"理性评估风险\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为评估风险的工具提及，帮助用户看清历史波动，辅助决策是否入场，逻辑自然。\",\"must_avoid\":[\"直接劝退或鼓励入场\",\"夸大收益或风险\",\"具体政策解读\"],\"risk_notes\":[\"避免被视为恐吓营销\",\"保持客观中立\"],\"topic_fingerprint\":{\"problem_core\":\"入场前的风险评估\",\"answer_angle\":\"认知门槛高于技术门槛\",\"target_pain\":\"不确定自己是否适合玩\",\"promo_entry\":\"用历史走势对比评估波动风险\"}},\"prefilterCachedAt\":\"2026-03-27T11:31:17.807Z\"}', 'P2', 80, '行情判断', '焦花花实测型', '[\"