INSERT INTO `topic_candidates` VALUES (138, 1, 'https://www.zhihu.com/question/628429086', '有哪些优秀的量化交易策略？', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T09:08:18.731Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"量化类核心选题，直接对应产品策略验证与回测能力。虽属量化类，但可通过强调\'策略逻辑验证\'而非\'直接给代码\'来承接产品，符合币圈≈交易>量化的平衡原则。\",\"title\":\"有哪些优秀的量化交易策略？别迷信“圣杯”，先懂这 3 种底层逻辑\",\"summary\":\"市面上策略无数，核心逻辑不过趋势、均值回归与套利。本文不直接给代码，而是拆解策略适用的市场环境。强调没有万能策略，只有经过多周期回测验证的逻辑才能存活。\",\"priority\":\"P1\",\"fit_score\":80,\"question_type\":\"策略构建\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"对量化感兴趣但无从下手的交易者\",\"寻找稳定策略的中级用户\"],\"pain_points\":[\"找不到靠谱策略\",\"盲目套用他人策略亏损\",\"不懂策略适用环境\"],\"recommended_angle\":\"分类讲解策略逻辑，强调\'环境适配性\'，自然引入用工具验证策略在不同行情下的表现。\",\"persona_hooks\":[\"见过太多人拿着趋势策略死扛震荡\",\"策略没有好坏，只有适不适合\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解\'验证策略适用环境\'时，自然提及可视化工具能快速切换周期测试，避免手动复盘的遗漏。\",\"must_avoid\":[\"提供具体可执行的交易代码\",\"承诺某策略永不亏损\",\"贬低主观交易\"],\"risk_notes\":[\"避免被视为提供投资建议\",\"强调策略也有失效期\"],\"topic_fingerprint\":{\"problem_core\":\"策略选择与适配\",\"answer_angle\":\"逻辑分类与环境验证\",\"target_pain\":\"策略失效亏损\",\"promo_entry\":\"多周期策略回测验证\"}},\"prefilterCachedAt\":\"2026-03-27T09:10:10.235Z\"}', 'P1', 80, '策略构建', '二牛实测型', '[\"提供具体可执行的交易代码\",\"承诺某策略永不亏损\",\"贬低主观交易\"]', '[\"避免被视为提供投资建议\",\"强调策略也有失效期\"]', 'valid', '量化类核心选题，直接对应产品策略验证与回测能力。虽属量化类，但可通过强调\'策略逻辑验证\'而非\'直接给代码\'来承接产品，符合币圈≈交易>量化的平衡原则。', '2026-03-27 17:10:10', 'blocked_duplicate', '总分低于 20，与历史题目在量化策略验证及产品切入点上重合度过高', '2026-03-27 17:08:18');
