INSERT INTO `topic_candidates` VALUES (154, 1, 'https://www.zhihu.com/question/2014717415645266005', '币圈2026年还能赚到钱吗？还是只剩机构割韭菜了？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"加密货币市场\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:08:03.671Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"直击散户生存痛点，契合交易类选题，可自然承接到风险管理、策略适配性与机构博弈分析。\",\"title\":\"2026 年币圈还能赚到钱吗？散户生存指南与机构博弈\",\"summary\":\"承认机构优势，但指出散户的灵活性机会。重点讲解如何在机构主导的市场中建立自己的小策略，利用工具验证策略有效性，避免被收割。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"亏损散户\",\"担心被割韭菜者\"],\"pain_points\":[\"觉得市场被操控\",\"找不到盈利模式\",\"恐惧未来环境\"],\"recommended_angle\":\"不否认机构优势，强调散户的\'小而美\'策略，用工具验证小资金策略的可行性。\",\"persona_hooks\":[\"我也曾被机构收割过\",\"小资金有小资金的打法\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解验证小策略时，提及回测工具能降低试错成本。\",\"must_avoid\":[\"承诺能战胜机构\",\"推荐具体对抗手法\",\"散布阴谋论\"],\"risk_notes\":[\"避免激化散户与机构对立\",\"保持理性客观\"],\"topic_fingerprint\":{\"problem_core\":\"散户生存空间\",\"answer_angle\":\"差异化策略验证\",\"target_pain\":\"被收割恐惧\",\"promo_entry\":\"小资金策略回测\"}},\"prefilterCachedAt\":\"2026-03-27T10:10:39.047Z\"}', 'P1', 85, '风险管理', '二牛踩坑型', '[\"承诺能战胜机构\",\"推荐具体对抗手法\",\"散布阴谋论\"]', '[\"避免激化散户与机构对立\",\"保持理性客观\"]', 'valid', '直击散户生存痛点，契合交易类选题，可自然承接到风险管理、策略适配性与机构博弈分析。', '2026-03-27 18:10:39', 'published', '{\"problem_core\":\"散户生存空间\",\"answer_angle\":\"差异化策略验证\",\"target_pain\":\"被收割恐惧\",\"promo_entry\":\"小资金策略回测\"}', '2026-03-27 18:08:03');
INSERT INTO `topic_candidates` VALUES (155, 1, 'https://www.zhihu.com/question/1994878609165403503', '加密货币市场近期波动持续放大，且比特币与全球M2货币供应脱钩加剧，对此你怎么看？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"加密货币市场\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:08:03.678Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"高质量宏观数据分析题，完美契合产品\'多币种交叉验证\'与\'数据可视化\'能力，适合展现专业度。\",\"title\":\"比特币与 M2 脱钩加剧？用数据回测看看历史相关性\",\"summary\":\"不凭感觉判断脱钩，而是拉取历史数据计算相关性系数。展示在不同宏观周期下，加密货币与流动性的真实关系，教用户用数据验证宏观观点。\",\"priority\":\"P0\",\"fit_score\":92,\"question_type\":\"方法验证\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"宏观交易者\",\"数据驱动型投资者\"],\"pain_points\":[\"宏观观点打架\",\"无法验证逻辑\",\"缺乏数据工具\"],\"recommended_angle\":\"用实际回测数据说话，展示相关性变化，强调\'验证\'比\'观点\'重要。\",\"persona_hooks\":[\"宏观不是靠嘴说的\",\"数据不会骗人\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"核心内容即为数据回测与相关性分析，自然展示产品可视化与交叉验证能力。\",\"must_avoid\":[\"断言脱钩永久有效\",\"过度简化宏观逻辑\",\"提供交易建议\"],\"risk_notes\":[\"避免宏观误读风险\",\"强调数据滞后性\"],\"topic_fingerprint\":{\"problem_core\":\"宏观相关性验证\",\"answer_angle\":\"数据回测分析\",\"target_pain\":\"宏观逻辑无法验证\",\"promo_entry\":\"多因子相关性回测\"}},\"prefilterCachedAt\":\"2026-03-27T10:10:39.052Z\"}', 'P0', 92, '方法验证', '二牛实测型', '[\"断言脱钩永久有效\",\"过度简化宏观逻辑\",\"提供交易建议\"]', '[\"避免宏观误读风险\",\"强调数据滞后性\"]', 'valid', '高质量宏观数据分析题，完美契合产品\'多币种交叉验证\'与\'数据可视化\'能力，适合展现专业度。', '2026-03-27 18:10:39', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-27 18:08:03');
INSERT INTO `topic_candidates` VALUES (156, 1, 'https://www.zhihu.com/question/1960291273849139598', '加密货币过去 24 小时全网爆仓升至 191.41 亿美元，再次刷新历史记录，发生了什么？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"加密货币市场\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:08:03.681Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"爆仓数据是极佳的风险教育素材，契合\'风险管理\'与\'交易纪律\'，可自然引入仓位管理与止损策略。\",\"title\":\"全网爆仓 191 亿美元背后：为什么你总是那个被清算的？\",\"summary\":\"分析爆仓数据的构成，指出高杠杆与无止损是主因。结合历史爆仓高峰后的市场走势，强调仓位管理的重要性，建议用模拟回测检验仓位风险。\",\"priority\":\"P1\",\"fit_score\":88,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"高杠杆用户\",\"频繁爆仓者\"],\"pain_points\":[\"控制不住杠杆\",\"不止损\",\"侥幸心理\"],\"recommended_angle\":\"用爆仓数据警示风险，提供具体的仓位管理建议，引入回测验证仓位安全性。\",\"persona_hooks\":[\"我也曾贡献过爆仓数据\",\"活下来比赚多少重要\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解仓位风险时，提及用工具模拟极端行情下的仓位表现。\",\"must_avoid\":[\"嘲笑爆仓用户\",\"推荐具体杠杆倍数\",\"鼓励反手做空\"],\"risk_notes\":[\"避免诱导反向操作\",\"强调杠杆高风险\"],\"topic_fingerprint\":{\"problem_core\":\"杠杆风险控制\",\"answer_angle\":\"爆仓数据警示\",\"target_pain\":\"重复爆仓\",\"promo_entry\":\"仓位风险模拟\"}},\"prefilterCachedAt\":\"2026-03-27T10:10:39.056Z\"}', 'P1', 88, '风险管理', '二牛踩坑型', '[\"嘲笑爆仓用户\",\"推荐具体杠杆倍数\",\"鼓励反手做空\"]', '[\"避免诱导反向操作\",\"强调杠杆高风险\"]', 'valid', '爆仓数据是极佳的风险教育素材，契合\'风险管理\'与\'交易纪律\'，可自然引入仓位管理与止损策略。', '2026-03-27 18:10:39', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-27 18:08:03');
INSERT INTO `topic_candidates` VALUES (157, 1, 'https://www.zhihu.com/question/1944002177254286362', '两万闲钱，稳妥买币好还是搏一搏好？', 'keyword_search', '{\"latestSourceType\":\"keyword_search\",\"discoveredSources\":[\"keyword_search\"],\"sourceEvents\":[{\"sourceType\":\"keyword_search\",\"metadata\":{\"keyword\":\"加密货币市场\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:08:03.683Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"具体资金量的决策问题，契合\'策略适配性\'与\'风险管理\'，适合给出务实的小资金生存建议。\",\"title\":\"两万闲钱进币圈：是稳妥买币还是搏一搏？算笔账给你看\",\"summary\":\"针对小资金特点，分析\'稳妥\'与\'搏一搏\'的真实期望值。建议先用小资金进行策略回测，验证胜率后再决定投入方式，避免赌徒心态。\",\"priority\":\"P1\",\"fit_score\":82,\"question_type\":\"策略构建\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"小资金散户\",\"犹豫入场者\"],\"pain_points\":[\"资金少怕错过\",\"怕亏光不敢动\",\"缺乏策略规划\"],\"recommended_angle\":\"算期望值账，强调小资金更应注重策略验证而非盲目博弈，引入模拟回测概念。\",\"persona_hooks\":[\"小钱也是钱，别乱糟蹋\",\"先验证再投入\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在建议验证策略时，提及可用工具进行低成本回测。\",\"must_avoid\":[\"推荐具体币种\",\"鼓励全仓搏杀\",\"忽视通胀风险\"],\"risk_notes\":[\"避免被视为理财建议\",\"强调本金安全\"],\"topic_fingerprint\":{\"problem_core\":\"小资金配置决策\",\"answer_angle\":\"期望值计算与验证\",\"target_pain\":\"资金少决策难\",\"promo_entry\":\"策略回测验证\"}},\"prefilterCachedAt\":\"2026-03-27T10:10:39.060Z\"}', 'P1', 82, '策略构建', '二牛经验型', '[\"推荐具体币种\",\"鼓励全仓搏杀\",\"忽视通胀风险\"]', '[\"避免被视为理财建议\",\"强调本金安全\"]', 'valid', '具体资金量的决策问题，契合\'策略适配性\'与\'风险管理\'，适合给出务实的小资金生存建议。', '2026-03-27 18:10:39', 'blocked', '当前批次已满，本轮不纳入。', '2026-03-27 18:08:03');
INSERT INTO `topic_candidates` VALUES (158, 2, 'https://www.zhihu.com/question/600714845', '人到底经历什么，才能大彻大悟？', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:11:04.350Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"虽与历史选题“太晚明白的道理”有语义重叠，但本题侧重“经历/事件”，可聚焦具体交易亏损事件带来的认知转折。能自然承接复盘与风控工具的价值，避免重复纯道理阐述。\",\"title\":\"交易生涯里，哪一次亏损让你真正大彻大悟？\",\"summary\":\"聚焦具体交易亏损事件，而非空谈道理。焦花花分享真实爆仓或大幅回撤经历，强调当时缺乏数据验证导致的盲目。引出若有回测工具可提前识别风险。适合建立真实感，自然植入工具在复盘中的辅助作用，避免说教。\",\"priority\":\"P2\",\"fit_score\":75,\"question_type\":\"入门认知\",\"persona_mode\":\"焦花花踩坑型\",\"target_audience\":[\"亏损交易者\",\"反思型投资者\",\"新手\"],\"pain_points\":[\"重复犯错\",\"缺乏复盘深度\",\"情绪化交易\"],\"recommended_angle\":\"用具体亏损案例引出工具验证的重要性，强调“经历痛苦不如经历数据”。\",\"persona_hooks\":[\"不回避亏损历史\",\"真实账户经历\",\"务实复盘态度\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为避免再次踩坑的解决方案提及，强调工具辅助复盘，不强行推销。\",\"must_avoid\":[\"具体金额炫耀\",\"过度卖惨\",\"保证以后不亏\"],\"risk_notes\":[\"避免具体币种推荐\",\"保持理性基调\"],\"topic_fingerprint\":{\"problem_core\":\"交易认知滞后\",\"answer_angle\":\"案例复盘 + 工具辅助\",\"target_pain\":\"重复犯错\",\"promo_entry\":\"辅助验证与复盘工具\"}},\"prefilterCachedAt\":\"2026-03-27T10:12:49.683Z\"}', 'P2', 75, '入门认知', '焦花花踩坑型', '[\"具体金额炫耀\",\"过度卖惨\",\"保证以后不亏\"]', '[\"避免具体币种推荐\",\"保持理性基调\"]', 'valid', '虽与历史选题“太晚明白的道理”有语义重叠，但本题侧重“经历/事件”，可聚焦具体交易亏损事件带来的认知转折。能自然承接复盘与风控工具的价值，避免重复纯道理阐述。', '2026-03-27 18:12:49', 'blocked_duplicate', '与历史题目“你人生中太晚明白的道理是什么？”在核心叙事（亏损 - 反思 - 工具）上高度重合，用户感知重复度高，且产品切入逻辑一致。', '2026-03-27 18:11:04');
INSERT INTO `topic_candidates` VALUES (159, 2, 'https://www.zhihu.com/question/629658395', '在明白什么道理后你就不再焦虑了？', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-03-27T10:11:04.353Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"交易焦虑是核心痛点，直接契合产品的风险管理与不确定性应对能力。焦花花人设适合分享如何通过数据验证降低不确定性，从而缓解焦虑，价值度高。\",\"title\":\"交易不再焦虑，是从承认“无法预测市场”开始的\",\"summary\":\"直击交易心理痛点，焦花花分享从预测转向应对的心路历程。强调通过历史数据回测建立概率优势，而非猜测涨跌。自然引入工具的场景验证功能，帮助用户建立交易计划，减少盘中情绪波动。适合建立信任感。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"风险管理\",\"persona_mode\":\"焦花花经验型\",\"target_audience\":[\"焦虑交易者\",\"持仓波动大用户\",\"心态不稳定新手\"],\"pain_points\":[\"持仓焦虑\",\"害怕踏空或爆仓\",\"情绪化决策\"],\"recommended_angle\":\"心理建设 + 方法论，将焦虑归因于不确定性，用工具数据作为解药。\",\"persona_hooks\":[\"心态平稳\",\"数据驱动决策\",\"不猜顶底\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品核心能力（回测、情景分析）直接解决“不确定性”带来的焦虑，植入逻辑顺畅。\",\"must_avoid\":[\"承诺收益\",\"鼓励杠杆\",\"制造焦虑\"],\"risk_notes\":[\"避免被视为投资建议\",\"数据需准确\"],\"topic_fingerprint\":{\"problem_core\":\"交易心理与不确定性\",\"answer_angle\":\"心态调整 + 数据验证\",\"target_pain\":\"持仓焦虑\",\"promo_entry\":\"历史走势对比与情景验证\"}},\"prefilterCachedAt\":\"2026-03-27T10:12:49.691Z\"}', 'P1', 85, '风险管理', '焦花花经验型', '[\"承诺收益\",\"鼓励杠杆\",\"制造焦虑\"]', '[\"避免被视为投资建议\",\"数据需准确\"]', 'invalid', 'network_or_page_error: page.goto: net::ERR_CONNECTION_CLOSED at https://www.zhihu.com/\nCall log:\n[2m  - navigating to \"https://www.zhihu.com/\", waiting until \"domcontentloaded\"[22m\n；页面或网络异常再次发生，终止本次任务。', '2026-03-27 19:23:50', 'publish_failed', 'network_or_page_error: page.goto: net::ERR_CONNECTION_CLOSED at https://www.zhihu.com/\nCall log:\n[2m  - navigating to \"https://www.zhihu.com/\", waiting until \"domcontentloaded\"[22m\n；页面或网络异常再次发生，终止本次任务。', '2026-03-27 18:11:04');
