INSERT INTO `topic_candidates` VALUES (176, 1, 'https://www.zhihu.com/question/1969142822910276249', '量化策略回测了过去至今17年，平均年化收益38%，但夏普比率只有0.9，这个策略的收益水平怎么样？', 'recommended_answer', '{\"latestSourceType\":\"recommended_answer\",\"discoveredSources\":[\"recommended_answer\"],\"sourceEvents\":[{\"sourceType\":\"recommended_answer\",\"metadata\":{\"page\":\"home_recommend\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:04:33.507Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"强量化类选题，直接对应产品回测与策略验证能力。虽与历史\'过拟合\'题有重叠，但本题侧重\'指标评估\'，可差异化切入夏普比率与收益的平衡。\",\"title\":\"回测年化 38% 夏普 0.9 靠谱吗？揭秘量化策略的真实风险\",\"summary\":\"拆解高收益低夏普背后的含义，指出波动过大或回撤过深的风险。强调不能只看收益率，要结合最大回撤和样本内外表现。引导用可视化工具多周期验证。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"方法验证\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"量化入门者\",\"策略开发者\",\"迷信回测数据者\"],\"pain_points\":[\"看不懂风险指标\",\"回测好实盘差\",\"忽视波动风险\"],\"recommended_angle\":\"从具体数据案例入手，教育用户如何正确评估策略质量，而非单纯追求高收益。\",\"persona_hooks\":[\"见过太多完美回测实盘崩盘\",\"夏普比率比收益率更重要\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解多周期验证和指标可视化时，自然提及工具能辅助判断策略稳定性。\",\"must_avoid\":[\"承诺策略有效\",\"提供具体代码\",\"贬低其他平台\"],\"risk_notes\":[\"避免被视为投资建议\",\"强调量化也有亏损风险\"],\"topic_fingerprint\":{\"problem_core\":\"策略指标评估\",\"answer_angle\":\"风险收益比分析\",\"target_pain\":\"实盘亏损风险\",\"promo_entry\":\"可视化回测与多周期验证\"}},\"prefilterCachedAt\":\"2026-04-02T16:06:22.303Z\"}', 'P1', 85, '方法验证', '二牛实测型', '[\"承诺策略有效\",\"提供具体代码\",\"贬低其他平台\"]', '[\"避免被视为投资建议\",\"强调量化也有亏损风险\"]', 'valid', '强量化类选题，直接对应产品回测与策略验证能力。虽与历史\'过拟合\'题有重叠，但本题侧重\'指标评估\'，可差异化切入夏普比率与收益的平衡。', '2026-04-03 00:06:22', 'new', NULL, '2026-04-03 00:04:33');
