INSERT INTO `topic_candidates` VALUES (179, 1, 'https://www.zhihu.com/question/1903041599820260280', '量化交易比手动交易好吗？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.957Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"交易与量化对比经典题，痛点清晰，可自然引入工具辅助决策逻辑，符合交易类与量化类平衡原则。\",\"title\":\"量化交易一定比手动交易强吗？老手告诉你两者的真实边界\",\"summary\":\"不吹捧量化也不神话手动，从执行纪律、情绪干扰、策略复杂度三个维度对比。指出量化是工具而非圣杯，适合无法克服人性弱点的人群，手动则胜在灵活性。\",\"priority\":\"P1\",\"fit_score\":80,\"question_type\":\"方法验证\",\"persona_mode\":\"二牛对比型\",\"target_audience\":[\"犹豫是否转量化的手动交易者\",\"迷信量化自动赚钱的新手\"],\"pain_points\":[\"手动交易情绪失控\",\"量化策略实盘失效\",\"不知道适合自己哪种方式\"],\"recommended_angle\":\"客观对比优劣，强调\'工具辅助人\'而非\'工具替代人\'，自然引入回测验证的重要性。\",\"persona_hooks\":[\"手动亏过也量化亏过\",\"工具是武器不是保姆\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讨论量化验证成本时，提及可视化工具能降低尝试门槛。\",\"must_avoid\":[\"承诺量化稳赚\",\"贬低手动交易\",\"推荐具体量化平台\"],\"risk_notes\":[\"避免绝对化结论\",\"强调风险共存\"],\"topic_fingerprint\":{\"problem_core\":\"交易方式选择\",\"answer_angle\":\"场景化对比分析\",\"target_pain\":\"选择困难与预期偏差\",\"promo_entry\":\"工具辅助决策与验证\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.089Z\"}', 'P1', 80, '方法验证', '二牛对比型', '[\"承诺量化稳赚\",\"贬低手动交易\",\"推荐具体量化平台\"]', '[\"避免绝对化结论\",\"强调风险共存\"]', 'valid', '交易与量化对比经典题，痛点清晰，可自然引入工具辅助决策逻辑，符合交易类与量化类平衡原则。', '2026-04-03 00:08:50', 'new', NULL, '2026-04-03 00:06:24');
INSERT INTO `topic_candidates` VALUES (180, 1, 'https://www.zhihu.com/question/2022414445943486011', 'AI炒股回测年化40%，实盘却亏损20%，问题出在算法还是人性？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.960Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"直击回测与实盘差异的核心痛点，高度契合产品回测验证能力，用户焦虑感强，易产生共鸣。\",\"title\":\"回测年化 40% 实盘却亏损？别只怪人性，先检查你的回测逻辑\",\"summary\":\"拆解回测完美的常见陷阱：未来函数、过拟合、滑点忽略。强调实盘亏损不一定是人性问题，可能是策略本身未经过样本外检验。建议用多周期数据交叉验证。\",\"priority\":\"P0\",\"fit_score\":90,\"question_type\":\"方法验证\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"回测党\",\"实盘亏损的量化尝试者\"],\"pain_points\":[\"回测数据欺骗性\",\"实盘心态崩盘\",\"找不到亏损真实原因\"],\"recommended_angle\":\"用技术细节拆解\'假盈利\'，弱化人性指责，强化验证流程的重要性。\",\"persona_hooks\":[\"见过太多完美曲线崩盘\",\"数据不会骗人但人会\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解样本外检验和多周期验证时，自然提及可视化工具能提高效率。\",\"must_avoid\":[\"承诺解决所有亏损\",\"提供具体代码\",\"贬低其他软件\"],\"risk_notes\":[\"避免被视为投资建议\",\"强调量化风险\"],\"topic_fingerprint\":{\"problem_core\":\"回测与实盘差异\",\"answer_angle\":\"技术归因而非人性归因\",\"target_pain\":\"实盘亏损困惑\",\"promo_entry\":\"严谨的回测验证流程\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.091Z\"}', 'P0', 90, '方法验证', '二牛实测型', '[\"承诺解决所有亏损\",\"提供具体代码\",\"贬低其他软件\"]', '[\"避免被视为投资建议\",\"强调量化风险\"]', 'invalid', 'network_or_page_error: Cannot read properties of undefined (reading \'w\')；页面或网络异常再次发生，终止本次任务。', '2026-04-27 20:05:56', 'published', 'network_or_page_error: Cannot read properties of undefined (reading \'w\')；页面或网络异常再次发生，终止本次任务。', '2026-04-03 00:06:24');
