INSERT INTO `topic_candidates` VALUES (182, 1, 'https://www.zhihu.com/question/2022360752523060641', '如何分析价格波动背后的驱动因子？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.971Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"交易分析核心方法论，属于交易类选题，可承接市场认知与策略验证，符合币圈≈交易>量化的权重原则。\",\"title\":\"价格波动背后到底是谁在推动？学会分析驱动因子再下单\",\"summary\":\"拒绝看图说话，从资金面、情绪面、基本面拆解波动原因。强调建立自己的分析框架，用历史数据验证因子有效性，而不是凭感觉猜涨跌。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"行情判断\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"盲目跟单者\",\"缺乏分析框架的交易者\"],\"pain_points\":[\"不知道为何涨跌\",\"追涨杀跌\",\"缺乏独立判断能力\"],\"recommended_angle\":\"方法论教学，强调\'验证因子\'而非\'预测行情\'，自然引入数据工具辅助分析。\",\"persona_hooks\":[\"不再听消息炒股\",\"只赚认知范围内的钱\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在讲解验证因子有效性时，提及工具可辅助回溯历史数据。\",\"must_avoid\":[\"推荐具体币种\",\"承诺分析准确\",\"涉及内幕消息\"],\"risk_notes\":[\"避免过度自信引导\",\"保持客观中立\"],\"topic_fingerprint\":{\"problem_core\":\"行情分析逻辑\",\"answer_angle\":\"驱动因子拆解与验证\",\"target_pain\":\"盲目交易\",\"promo_entry\":\"数据回溯与验证\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.099Z\"}', 'P1', 85, '行情判断', '二牛经验型', '[\"推荐具体币种\",\"承诺分析准确\",\"涉及内幕消息\"]', '[\"避免过度自信引导\",\"保持客观中立\"]', 'valid', '交易分析核心方法论，属于交易类选题，可承接市场认知与策略验证，符合币圈≈交易>量化的权重原则。', '2026-04-03 00:08:50', 'new', NULL, '2026-04-03 00:06:24');
INSERT INTO `topic_candidates` VALUES (183, 1, 'https://www.zhihu.com/question/2021492828706972407', '在已经明确目标的前提下，若现有策略效果没有达到预期，如何判断自己应该继续投入还是更换策略？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.975Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"策略生命周期管理的高阶问题，直击交易者决策难点，高度契合产品策略验证与风险管理能力。\",\"title\":\"策略失效是该坚持还是放弃？用这三项指标做决策而不是靠感觉\",\"summary\":\"区分正常回撤与策略失效的界限。介绍最大回撤、恢复周期、市场适配性三个评估维度。建议用工具进行样本外测试，避免在低谷期盲目换策略。\",\"priority\":\"P0\",\"fit_score\":88,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛实测型\",\"target_audience\":[\"策略遭遇回撤的交易者\",\"频繁更换策略的亏损者\"],\"pain_points\":[\"无法判断策略是否失效\",\"低谷期心态崩溃\",\"频繁切换导致亏损\"],\"recommended_angle\":\"量化评估标准替代主观感觉，强调纪律与数据验证，自然引入回测工具辅助决策。\",\"persona_hooks\":[\"曾经因为盲目换策略亏惨\",\"数据比感觉靠谱\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解评估维度时，提及工具可自动化计算这些指标并进行历史验证。\",\"must_avoid\":[\"承诺策略永不失效\",\"提供具体参数\",\"鼓励扛单\"],\"risk_notes\":[\"避免误导用户死扛亏损\",\"强调止损纪律\"],\"topic_fingerprint\":{\"problem_core\":\"策略生命周期管理\",\"answer_angle\":\"数据化决策标准\",\"target_pain\":\"决策迷茫与心态失控\",\"promo_entry\":\"策略评估与回测验证\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.101Z\"}', 'P0', 88, '风险管理', '二牛实测型', '[\"承诺策略永不失效\",\"提供具体参数\",\"鼓励扛单\"]', '[\"避免误导用户死扛亏损\",\"强调止损纪律\"]', 'invalid', 'network_or_page_error: locator.textContent: Target page, context or browser has been closed\nCall log:\n  - waiting for locator(\'button\').nth(55)\n；页面或网络异常再次发生，终止本次任务。', '2026-04-08 23:07:40', 'publish_failed', 'network_or_page_error: locator.textContent: Target page, context or browser has been closed\nCall log:\n  - waiting for locator(\'button\').nth(55)\n；页面或网络异常再次发生，终止本次任务。', '2026-04-03 00:06:24');
