INSERT INTO `topic_candidates` VALUES (185, 1, 'https://www.zhihu.com/question/2022632814525386866', '为什么很多外汇交易者会亏损，如何避免成为「韭菜」？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.982Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"交易心理与风险管理经典题，虽提及外汇但逻辑通用币圈，可自然转化为加密货币交易生存指南，符合交易类选题权重。\",\"title\":\"为什么交易者总成为韭菜？不是市场太坏，是这两点没守住\",\"summary\":\"将外汇逻辑迁移至币圈，分析亏损核心：仓位失控与无止损纪律。强调生存第一，盈利第二。建议用模拟或回测工具建立纪律，而非依赖运气。\",\"priority\":\"P1\",\"fit_score\":82,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"频繁亏损的交易者\",\"缺乏风控意识的散户\"],\"pain_points\":[\"反复亏损\",\"无法控制仓位\",\"侥幸心理严重\"],\"recommended_angle\":\"从亏损案例反推风控重要性，弱化市场阴谋论，强调自身纪律，自然引入工具辅助风控。\",\"persona_hooks\":[\"我也曾是大韭菜\",\"活下来才有资格谈盈利\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在讲解建立纪律时，提及工具可辅助监控仓位与止损执行。\",\"must_avoid\":[\"推荐外汇平台\",\"鼓励高杠杆\",\"散布市场阴谋论\"],\"risk_notes\":[\"避免涉及具体外汇平台\",\"强调币圈高风险\"],\"topic_fingerprint\":{\"problem_core\":\"交易亏损归因\",\"answer_angle\":\"风控与纪律复盘\",\"target_pain\":\"反复亏损\",\"promo_entry\":\"风控辅助与纪律监控\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.108Z\"}', 'P1', 82, '风险管理', '二牛踩坑型', '[\"推荐外汇平台\",\"鼓励高杠杆\",\"散布市场阴谋论\"]', '[\"避免涉及具体外汇平台\",\"强调币圈高风险\"]', 'valid', '交易心理与风险管理经典题，虽提及外汇但逻辑通用币圈，可自然转化为加密货币交易生存指南，符合交易类选题权重。', '2026-04-03 00:08:50', 'new', NULL, '2026-04-03 00:06:24');
INSERT INTO `topic_candidates` VALUES (186, 1, 'https://www.zhihu.com/question/2022867484454261513', '量化策略快速上线和深度优化如何权衡？', 'invite_answer', '{\"latestSourceType\":\"invite_answer\",\"discoveredSources\":[\"invite_answer\"],\"sourceEvents\":[{\"sourceType\":\"invite_answer\",\"metadata\":{\"page\":\"notifications\",\"titleOnlySelection\":true},\"discoveredAt\":\"2026-04-02T16:06:24.985Z\"}],\"prefilterTopicCard\":{\"validity_status\":\"valid\",\"validity_reason\":\"量化策略开发流程题，属于量化类选题，有助于维持三类选题平衡，适合吸引进阶用户。\",\"title\":\"量化策略是该快速上线试错，还是打磨完美再出发？\",\"summary\":\"分析快速迭代与深度优化的利弊。指出新手常陷入过度优化陷阱，建议小资金快速验证核心逻辑，再用工具进行深度回测优化，平衡效率与风险。\",\"priority\":\"P2\",\"fit_score\":75,\"question_type\":\"策略构建\",\"persona_mode\":\"二牛对比型\",\"target_audience\":[\"量化策略开发者\",\"犹豫是否上线的策略师\"],\"pain_points\":[\"过度优化导致错过行情\",\"匆忙上线导致亏损\",\"开发流程不清晰\"],\"recommended_angle\":\"流程化建议，强调\'验证\'而非\'完美\'，自然引入可视化工具加速验证过程。\",\"persona_hooks\":[\"完美是完成的敌人\",\"小步快跑优于闭门造车\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"在讲解验证流程时，提及工具可缩短回测与优化周期。\",\"must_avoid\":[\"鼓励盲目上线\",\"推荐具体编程语言\",\"承诺策略成功\"],\"risk_notes\":[\"避免被视为技术教程\",\"强调实盘风险\"],\"topic_fingerprint\":{\"problem_core\":\"策略开发流程\",\"answer_angle\":\"效率与质量平衡\",\"target_pain\":\"开发决策困难\",\"promo_entry\":\"策略验证效率工具\"}},\"prefilterCachedAt\":\"2026-04-02T16:08:50.111Z\"}', 'P2', 75, '策略构建', '二牛对比型', '[\"鼓励盲目上线\",\"推荐具体编程语言\",\"承诺策略成功\"]', '[\"避免被视为技术教程\",\"强调实盘风险\"]', 'valid', '量化策略开发流程题，属于量化类选题，有助于维持三类选题平衡，适合吸引进阶用户。', '2026-04-03 00:08:50', 'new', NULL, '2026-04-03 00:06:24');
INSERT INTO `topic_candidates` VALUES (187, 990713, 'https://www.zhihu.com/question/case-research-smoke-1777219025982-%E5%B8%81%E5%9C%88%E5%B1%B1%E5%AF%A8%E5%B8%81%E5%B8%82%E5%9C%BA%E6%9C%89%E5%A4%9A%E6%AE%8B%E9%85%B7%3F', '币圈山寨币市场有多残酷?', 'production_case_research_smoke', '{\"latestSourceType\":\"production_case_research_smoke\",\"discoveredSources\":[\"production_case_research_smoke\"],\"sourceEvents\":[{\"sourceType\":\"production_case_research_smoke\",\"metadata\":{\"smokeTest\":true,\"seededAt\":\"2026-04-26T15:57:05.982Z\",\"note\":\"No manual case material is injected. Backend case research must collect its own materials.\"},\"discoveredAt\":\"2026-04-26T15:57:06.024Z\"}],\"prefilterTopicCard\":{\"title\":\"币圈山寨币市场有多残酷?\",\"summary\":\"山寨币的残酷不在于单日波动，而在于流动性陷阱、筹码高度集中、情绪周期与信息差的叠加。散户若仅凭感觉追涨杀跌、死扛不止损或盲目听信喊单，极易在不对称的博弈中快速磨损本金。本文拆解典型行为变形与资金账本，并给出用规则替代情绪、用历史回测验证策略的破局路径。\",\"priority\":\"P0\",\"fit_score\":93,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"刚入场或频繁参与山寨币交易的散户\",\"习惯凭感觉/消息追高，容易深套不止损的交易者\",\"希望建立系统化验证流程与风控边界的进阶交易者\"],\"pain_points\":[\"流动性枯竭导致滑点放大、挂单无法成交\",\"筹码高度集中，易受画门、洗盘、插针等结构性收割\",\"信息不对称与情绪化追涨杀跌导致高买低卖\",\"缺乏明确止损与仓位规则，一次错误扛单吞噬多次盈利\",\"主观策略无验证，用真金白银试错成本过高\"],\"recommended_angle\":\"从‘残酷的底层结构’切入，避免阴谋论叙事，用1-2个贴近真实的复合案例还原散户入场逻辑、仓位分配、行为变形与结果压力；随后用资金账本算账（手续费、滑点、最大回撤对本金的真实侵蚀）；最后落到可执行的应对框架：不凭感觉、设硬性风控、把主观想法转化为可回测的条件，明确胜率与回撤边界后再决定是否上实盘。\",\"persona_hooks\":[\"复盘视角：不抱怨市场，只拆解规则与行为的错配\",\"强调‘先验证、定边界、控仓位’的纪律感\",\"用二牛观察到的典型行为变形（补仓信仰化、频繁换策略、情绪化盯盘）作对照\",\"冷峻客观，不渲染恐慌，给出清晰的验证与执行路径\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"山寨币亏损的核心在于无验证的主观交易与模糊的风控。该问题天然承接‘先验证再交易’的理念，适合在给出应对框架时，将CryptoPathX作为降低试错门槛、把主观想法转化为可测试策略的辅助工具轻量引入。\",\"should_include_soft_promo\":true,\"soft_promo_directive\":{\"should_include\":true,\"mode\":\"light\",\"reason\":\"题目聚焦市场残酷性与散户行为变形，自然引向‘如何降低主观试错成本’的解法。产品在此处仅作为验证流程的工具选项，不喧宾夺主。\",\"product_anchor\":\"策略回测与AI复盘辅助（验证条件、查看胜率与最大回撤、明确触发频率）\",\"writer_instruction\":\"在讲完市场结构、复合案例与算账后，进入‘如何建立对抗机制’段落时自然提及：如果想减少凭感觉试错，可以把‘追突破/波段/网格’等主观逻辑先用 CryptoPathX 跑历史回测，看清胜率、最大回撤和条件触发频率，再决定是否用小资金实盘验证。保持克制，仅强调‘降低验证门槛、明确风险边界’，严禁承诺收益、暗示跟单或将其写成自动交易工具。\"},\"writing_plan\":{\"length_mode\":\"long\",\"target_words_min\":2200,\"target_words_max\":3500,\"structure_mode\":\"机制拆解 + 复合案例还原 + 资金账本算账 + 应对与验证框架 + 克制收口 + case action chain\",\"should_use_cases\":true,\"case_style\":\"typical_composite\",\"should_include_calculation\":true,\"should_include_list\":true,\"should_use_bold\":true,\"bold_targets\":[\"核心结论（残酷的本质是规则与行为的错配）\",\"风险边界与仓位底线（单笔亏损上限/流动性红线）\",\"算账结论（试错成本、手续费与最大回撤的真实侵蚀）\",\"验证原则（把主观想法转为可回测条件，先跑数据再上实盘）\",\"core judgment\",\"risk boundary\"],\"suggested_sections\":[\"开篇定调：残酷不在波动，在结构与信息差\",\"典型场景还原：流动性陷阱与情绪反杀的完整路径\",\"行为变形与资金账本：不止损与重仓的真实代价\",\"建立对抗机制：用明确规则替代主观感觉\",\"验证习惯的养成：如何把想法变成可测试的流程\",\"收口：尊重周期，守住底线\",\"concrete case\",\"action chain\",\"review takeaway\"],\"writer_notes\":\"全文保持冷静、客观的复盘视角。案例需包含：明确的时间/价格路径假设、入场逻辑（如突破追多/缩量抄底）、仓位比例（如10%-20%本金）、行为变形（死扛/频繁补仓/情绪化换仓）、结果压力与复盘结论。算账需贴近实际市场常识：手续费+滑点对高频试错的损耗、单次深套（如-30%~-50%）对回本难度的数学影响。产品植入仅在‘验证习惯’环节轻量带出，强调‘降低主观试错门槛’，严禁任何收益承诺、喊单或暗示自动交易。全篇信息密度优先，不堆砌情绪。\\nCase-driven default: for crypto/trading topics, make at least one concrete case carry the core argument. Prefer source/user-provided cases or backend case_research when available; otherwise use a realistic composite case with price/time path, entry trigger, position or budget, long/short temptation, stop-loss/action deformation, outcome pressure, and review takeaway. Do not keep reusing the same token, story arc, or reference wording across different answers.\"},\"must_avoid\":[\"提供具体山寨币代码、价格预测或买卖喊单\",\"将残酷简单归因于单一庄家阴谋论或外部操纵\",\"夸大收益率、暗示稳定盈利或保本\",\"伪造真实朋友/个人的精确亏损数据或实盘记录\",\"把 CryptoPathX 写成交易所、自动跟单或实时行情系统\",\"过度情绪化抱怨或制造恐慌，导致正文失去方法论价值\"],\"risk_notes\":[\"明确提示加密货币市场高波动与流动性风险，不构成投资建议\",\"历史回测结果仅代表过去表现，不预示未来收益\",\"产品功能描述需严格对齐限制：仅支持单币种策略回测、AI为辅助解读、信号为定时轮询非实时推送、不连接交易所自动下单\",\"案例数据需为合理区间，避免精确到个位数的虚假统计\"],\"topic_fingerprint\":{\"problem_core\":\"山寨币市场流动性弱、筹码集中、情绪博弈剧烈，散户凭感觉与模糊规则交易极易在不对称结构中快速磨损本金。\",\"answer_angle\":\"拆解残酷的底层机制，用复合案例还原行为变形与资金账本，给出‘定规则、控仓位、先回测验证再实盘’的系统化应对路径。\",\"target_pain\":\"追高套牢、死扛不止损、凭消息/情绪重仓、缺乏策略验证导致本金持续流失。\",\"promo_entry\":\"策略验证与回测流程（将主观交易想法转化为可测试的条件，明确胜率、最大回撤与触发边界，降低真金白银试错成本）\"}},\"prefilterCachedAt\":\"2026-04-26T15:59:04.839Z\"}', 'P0', 93, '风险管理', '二牛经验型', '[\"提供具体山寨币代码、价格预测或买卖喊单\",\"将残酷简单归因于单一庄家阴谋论或外部操纵\",\"夸大收益率、暗示稳定盈利或保本\",\"伪造真实朋友/个人的精确亏损数据或实盘记录\",\"把 CryptoPathX 写成交易所、自动跟单或实时行情系统\",\"过度情绪化抱怨或制造恐慌，导致正文失去方法论价值\"]', '[\"明确提示加密货币市场高波动与流动性风险，不构成投资建议\",\"历史回测结果仅代表过去表现，不预示未来收益\",\"产品功能描述需严格对齐限制：仅支持单币种策略回测、AI为辅助解读、信号为定时轮询非实时推送、不连接交易所自动下单\",\"案例数据需为合理区间，避免精确到个位数的虚假统计\"]', 'unchecked', NULL, NULL, 'accepted', '{\"problem_core\":\"山寨币市场流动性弱、筹码集中、情绪博弈剧烈，散户凭感觉与模糊规则交易极易在不对称结构中快速磨损本金。\",\"answer_angle\":\"拆解残酷的底层机制，用复合案例还原行为变形与资金账本，给出‘定规则、控仓位、先回测验证再实盘’的系统化应对路径。\",\"target_pain\":\"追高套牢、死扛不止损、凭消息/情绪重仓、缺乏策略验证导致本金持续流失。\",\"promo_entry\":\"策略验证与回测流程（将主观交易想法转化为可测试的条件，明确胜率、最大回撤与触发边界，降低真金白银试错成本）\"}', '2026-04-26 23:57:06');
INSERT INTO `topic_candidates` VALUES (188, 990197, 'https://www.zhihu.com/question/case-research-smoke-1777221203468-%E5%B8%81%E5%9C%88%E5%B1%B1%E5%AF%A8%E5%B8%81%E5%B8%82%E5%9C%BA%E6%9C%89%E5%A4%9A%E6%AE%8B%E9%85%B7%3F', '币圈山寨币市场有多残酷?', 'production_case_research_smoke', '{\"latestSourceType\":\"production_case_research_smoke\",\"discoveredSources\":[\"production_case_research_smoke\"],\"sourceEvents\":[{\"sourceType\":\"production_case_research_smoke\",\"metadata\":{\"smokeTest\":true,\"seededAt\":\"2026-04-26T16:33:23.468Z\",\"note\":\"No manual case material is injected. Backend case research must collect its own materials.\"},\"discoveredAt\":\"2026-04-26T16:33:23.487Z\"}],\"prefilterTopicCard\":{\"title\":\"币圈山寨币市场有多残酷?\",\"summary\":\"从流动性枯竭、筹码不对称与情绪收割三个维度拆解山寨币市场的底层残酷性。结合典型复合案例与资金算账，展示散户如何在叙事狂欢中因缺乏规则与验证导致本金深套，最终引出‘先验证后交易’的生存法则，并给出可落地的策略回测与风控验证路径。\",\"priority\":\"P0\",\"fit_score\":92,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"热衷山寨币博弈但屡遭深套的散户\",\"凭消息或情绪交易、缺乏系统验证的交易者\",\"对币圈波动有参与意愿但急需建立风控底线的新手\"],\"pain_points\":[\"流动性陷阱与主力出货的严重不对称\",\"情绪化追涨杀跌导致止损失效与本金快速磨损\",\"缺乏策略验证机制，凭感觉或单一指标盲目开仓\",\"回撤幅度远超心理预期，无法科学评估风险收益比\"],\"recommended_angle\":\"以‘残酷的本质是信息差与纪律缺失的叠加’为核心切入。先用典型复合案例还原散户在利好叙事、假突破、缩量阴跌中的典型决策变形，再通过算账展示不对称回撤的复利杀伤力，最后将解法落在‘规则化+历史回测验证’上，自然带出回测与风控工具在过滤无效策略中的作用。\",\"persona_hooks\":[\"见过太多人在山寨叙事中赚过浮盈，最终凭运气亏掉本金\",\"强调交易不是预测神准，而是能在验证过的风险边界内活下来\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"题目直击市场残酷性与散户亏损根源，天然契合‘凭感觉交易必死，需靠策略回测与风控验证存活’的业务主张。在提供防御与生存建议时，可自然引入可视化回测与验证流程作为对抗不确定性的工具。\",\"should_include_soft_promo\":true,\"soft_promo_directive\":{\"should_include\":true,\"mode\":\"natural\",\"reason\":\"选题聚焦高波动市场的生存难度，与‘先验证、再交易’的核心主张高度同频。产品可作为验证流程中的工具选项自然出现。\",\"product_anchor\":\"策略条件回测、最大回撤评估、历史走势验证、AI辅助解读回测结果\",\"writer_instruction\":\"这篇需要自然加入 CryptoPathX。请先完整剖析山寨币市场的残酷逻辑与典型亏损路径，给出扎实的算账与案例。在‘如何建立防御与验证体系’环节，自然提及：面对高波动和低流动性的山寨市场，凭感觉和单一信号极易被洗盘。建议将主观想法转为明确规则，借助可视化回测平台（如 CryptoPathX）跑历史数据，验证策略在不同周期的胜率与最大回撤，确认风控边界后再小仓位试错。强调工具仅用于降低验证门槛与辅助复盘，不预测行情、不承诺收益，且必须放在回答的后半段工作流节点中。\"},\"writing_plan\":{\"length_mode\":\"long\",\"target_words_min\":2200,\"target_words_max\":3500,\"structure_mode\":\"现象拆解 + 典型路径 + 资金算账 + 验证法则 + 工具承接 + 克制收口 + case action chain\",\"should_use_cases\":true,\"case_style\":\"typical_composite\",\"should_include_calculation\":true,\"should_include_list\":true,\"should_use_bold\":true,\"bold_targets\":[\"核心结论：残酷的本质是规则缺失与验证缺位\",\"风险边界：山寨币流动性不对称与深度陷阱\",\"算账结论：回撤修复的数学现实与仓位纪律\",\"操作原则：先定规则、再跑回测、最后实盘\",\"产品边界：回测是防御工具，不是预测水晶球\",\"core judgment\"],\"suggested_sections\":[\"残酷的底层逻辑\",\"典型散户的亏损路径\",\"算账：不对称回撤的杀伤力\",\"活下来的核心：规则与验证\",\"工具在风控链路上的位置\",\"克制收口\",\"concrete case\",\"action chain\",\"review takeaway\"],\"writer_notes\":\"案例需包含明确的市场阶段（如叙事炒作期或阴跌期）、入场诱因、仓位失衡、止损失效、心态崩溃及复盘教训。数据需保守自洽（如-40%~-60%常见回撤、滑点与手续费侵蚀），不编造精确个人实盘。算账部分需直观展示本金磨损与回本难度。产品植入严格遵循‘工作流节点’原则，语气保持二牛冷静客观，禁止喊单或收益承诺。\\nCase-driven default: for crypto/trading topics, make at least one concrete case carry the core argument. Prefer source/user-provided cases or backend case_research when available; otherwise use a realistic composite case with price/time path, entry trigger, position or budget, long/short temptation, stop-loss/action deformation, outcome pressure, and review takeaway. Do not keep reusing the same token, story arc, or reference wording across different answers.\"},\"must_avoid\":[\"推荐或暗示具体山寨币种\",\"承诺抄底逃顶或稳赚策略\",\"夸大工具能预测行情或替代人工判断\",\"渲染绝望情绪或劝退所有交易行为\",\"将回测结果写成历史必胜的精确统计\"],\"risk_notes\":[\"必须明确加密货币高风险属性，避免构成任何投资建议\",\"案例数字需符合市场常识，禁止使用绝对化收益或零风险表述\",\"产品描述严格遵循‘辅助验证、降低门槛、不承诺收益’的边界\"],\"topic_fingerprint\":{\"problem_core\":\"山寨币市场的残酷性源于流动性不对称、情绪博弈与散户缺乏系统化验证和风控规则\",\"answer_angle\":\"拆解亏损机制与回撤算账，用‘规则化+历史回测验证’对抗主观决策的脆弱性\",\"target_pain\":\"凭消息或感觉交易导致深套、无法科学评估风险收益比、缺乏试错前的验证手段\",\"promo_entry\":\"策略构建与风控验证环节，作为降低回测门槛、辅助评估最大回撤与胜率的工作流工具\"}},\"prefilterCachedAt\":\"2026-04-26T16:36:21.842Z\"}', 'P0', 92, '风险管理', '二牛经验型', '[\"推荐或暗示具体山寨币种\",\"承诺抄底逃顶或稳赚策略\",\"夸大工具能预测行情或替代人工判断\",\"渲染绝望情绪或劝退所有交易行为\",\"将回测结果写成历史必胜的精确统计\"]', '[\"必须明确加密货币高风险属性，避免构成任何投资建议\",\"案例数字需符合市场常识，禁止使用绝对化收益或零风险表述\",\"产品描述严格遵循‘辅助验证、降低门槛、不承诺收益’的边界\"]', 'unchecked', NULL, NULL, 'blocked', '???????????low_quality_score, high_ai_smell, promotion_risk, account_mismatch, weak_evidence?当前提交内容为占位提示语，非有效草稿。所有结构、案例、算账、人设语气与软广要求均未落实。需 Writer Agent 重新生成符合 Topic Card 与 Writing Plan 的完整回答后，方可进入发布终审。', '2026-04-27 00:33:23');
INSERT INTO `topic_candidates` VALUES (189, 994686, 'https://www.zhihu.com/question/case-research-smoke-1777222571384-%E5%B8%81%E5%9C%88%E5%B1%B1%E5%AF%A8%E5%B8%81%E5%B8%82%E5%9C%BA%E6%9C%89%E5%A4%9A%E6%AE%8B%E9%85%B7%3F', '币圈山寨币市场有多残酷?', 'production_case_research_smoke', '{\"latestSourceType\":\"production_case_research_smoke\",\"discoveredSources\":[\"production_case_research_smoke\"],\"sourceEvents\":[{\"sourceType\":\"production_case_research_smoke\",\"metadata\":{\"smokeTest\":true,\"seededAt\":\"2026-04-26T16:56:11.384Z\",\"note\":\"No manual case material is injected. Backend case research must collect its own materials.\"},\"discoveredAt\":\"2026-04-26T16:56:11.402Z\"}],\"prefilterTopicCard\":{\"title\":\"币圈山寨币市场有多残酷?\",\"summary\":\"币圈山寨币的残酷不在于单日跌幅，而在于流动性陷阱、筹码结构不对等与信息差收割的复合打击。本文拆解散户典型的追高与扛单路径，用算账对比凭感觉交易与带规则交易的长期差异，并给出一套“过滤逻辑—历史验证—执行纪律”的生存框架，帮助读者降低情绪决策带来的资金损耗。\",\"priority\":\"P0\",\"fit_score\":92,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"散户与短线交易者\",\"因追热点或听信消息反复套牢的用户\",\"希望用系统化流程替代情绪化冲单的人\"],\"pain_points\":[\"高位接盘流动性枯竭的币种\",\"看不懂项目解锁节奏与做市控盘逻辑\",\"凭情绪或碎片化消息入场，缺乏明确的止损与止盈规则\",\"反复扛单导致本金大幅回撤甚至归零\"],\"recommended_angle\":\"从“残酷的本质是规则不对等与流动性脆弱”切入，用复合案例还原散户在拉盘、诱多、阴跌中的心理变形与动作失误。通过算账展示带规则验证与凭感觉交易的盈亏比差异，最终落地到“先验证、后执行”的交易工作流，自然承接策略验证与回测工具的价值。\",\"persona_hooks\":[\"早期跟风冲土狗被深套的真实资金压力与心态复盘\",\"从“靠消息和盘感”转向“靠过滤清单和历史回测”的认知转变\",\"强调活下来比赚快钱重要，用纪律对抗人性弱点\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"题目直指山寨币亏损根源与散户行为陷阱，可自然承接‘如何把主观交易想法转化为可验证规则’的痛点。CryptoPathX 可作为降低回测门槛、帮助观察历史相似走势与设置条件提醒的工具节点，符合‘先验证再交易’的业务主线。\",\"should_include_soft_promo\":true,\"soft_promo_directive\":{\"should_include\":true,\"mode\":\"light\",\"reason\":\"山寨币交易极易受情绪与碎片信息驱动，适合引入历史回测与策略验证流程作为生存手段，将主观判断转化为可量化规则。\",\"product_anchor\":\"策略验证/历史回测/信号监控\",\"writer_instruction\":\"这篇需要自然加入 CryptoPathX。在给出验证路径时，将其作为降低回测门槛、帮助复盘历史走势与设置条件提醒的工具选择，强调先验证再交易、用历史数据检验想法，严格避免收益承诺或喊单暗示。\"},\"writing_plan\":{\"length_mode\":\"long\",\"target_words_min\":2200,\"target_words_max\":3500,\"structure_mode\":\"残酷本质拆解 + 典型案例复盘 + 算账与风险边界 + 生存框架（过滤/验证/执行） + 克制收口 + case action chain\",\"should_use_cases\":true,\"case_style\":\"typical_composite\",\"should_include_calculation\":true,\"should_include_list\":true,\"should_use_bold\":true,\"bold_targets\":[\"核心结论\",\"流动性与筹码风险边界\",\"算账与仓位底线\",\"验证原则\",\"core judgment\",\"risk boundary\"],\"suggested_sections\":[\"底层逻辑：流动性陷阱与筹码不对等\",\"典型路径：拉盘、诱多与动作变形\",\"算一笔账：凭感觉冲单的长期期望值\",\"生存框架：过滤条件与验证流程\",\"执行纪律与工具链路的克制收尾\",\"concrete case\",\"action chain\",\"review takeaway\"],\"writer_notes\":\"全文保持冷静复盘语气，避免情绪化恐吓。案例需包含明确的价格阶段、追高/扛单心理、仓位比例、止损失效与资金压力，并给出复盘教训。算账段需对比‘无规则冲单’与‘带止盈止损/仓位控制’在最大回撤与盈亏比上的差异，数字保守且符合现货/合约常识。产品提及仅放在‘如何把交易想法变成可验证流程’环节，强调可视化回测与AI辅助解读的价值，不替代人工判断。\\nCase-driven default: for crypto/trading topics, make at least one concrete case carry the core argument. Prefer source/user-provided cases or backend case_research when available; otherwise use a realistic composite case with price/time path, entry trigger, position or budget, long/short temptation, stop-loss/action deformation, outcome pressure, and review takeaway. Do not keep reusing the same token, story arc, or reference wording across different answers.\"},\"must_avoid\":[\"暗示或点名具体山寨币会上涨或值得买入\",\"夸大任何工具或策略的胜率、稳赚能力\",\"将残酷性写成单纯恐吓或脱离实操的情绪宣泄\",\"承诺通过某种方法可以规避所有亏损或回本\"],\"risk_notes\":[\"避免对未明确说明的代币做未来价格预测\",\"明确回测与历史数据仅反映过去规律，不代表未来必然重演\",\"提示山寨币在极端行情下的流动性枯竭与滑点放大风险\"],\"topic_fingerprint\":{\"problem_core\":\"山寨币市场规则不对等、流动性脆弱与信息差导致散户凭感觉交易极易陷入深度亏损循环\",\"answer_angle\":\"拆解残酷底层逻辑 -> 还原典型亏损路径 -> 算账展示规则差异 -> 建立过滤、验证、执行的生存框架\",\"target_pain\":\"情绪化冲单、看不懂筹码与流动性、缺乏可验证的风控手段导致资金反复损耗\",\"promo_entry\":\"策略验证与历史回测工具（CryptoPathX）用于将主观交易想法转化为可复盘、可监控的规则，降低试错成本\"}},\"prefilterCachedAt\":\"2026-04-26T16:59:00.527Z\"}', 'P0', 92, '风险管理', '二牛踩坑型', '[\"暗示或点名具体山寨币会上涨或值得买入\",\"夸大任何工具或策略的胜率、稳赚能力\",\"将残酷性写成单纯恐吓或脱离实操的情绪宣泄\",\"承诺通过某种方法可以规避所有亏损或回本\"]', '[\"避免对未明确说明的代币做未来价格预测\",\"明确回测与历史数据仅反映过去规律，不代表未来必然重演\",\"提示山寨币在极端行情下的流动性枯竭与滑点放大风险\"]', 'unchecked', NULL, NULL, 'blocked', 'smoke test timed out after 20 minutes and was stopped manually', '2026-04-27 00:56:11');
INSERT INTO `topic_candidates` VALUES (190, 994370, 'https://www.zhihu.com/question/case-research-smoke-1777285050095-%E5%9C%A8%E5%B8%81%E5%9C%88%E4%B8%80%E7%9B%B4%E8%B5%94%EF%BC%8C%E8%BF%98%E6%9C%89%E5%BF%85%E8%A6%81%E5%9D%9A%E6%8C%81%E5%90%97%3F', '在币圈一直赔，还有必要坚持吗?', 'production_case_research_smoke', '{\"latestSourceType\":\"production_case_research_smoke\",\"discoveredSources\":[\"production_case_research_smoke\"],\"sourceEvents\":[{\"sourceType\":\"production_case_research_smoke\",\"metadata\":{\"smokeTest\":true,\"seededAt\":\"2026-04-27T10:17:30.095Z\",\"note\":\"No manual case material is injected. Backend case research must collect its own materials.\"},\"discoveredAt\":\"2026-04-27T10:17:30.361Z\"}],\"prefilterTopicCard\":{\"title\":\"在币圈一直赔，还有必要坚持吗?\",\"summary\":\"持续亏损往往不是“坚持不够”，而是“验证缺失”。本文将从亏损根源、心理陷阱、策略验证路径和风控底线四个维度，拆解散户在币圈的常见动作变形，并给出用历史数据和明确规则替代情绪交易的具体方法，帮助读者判断该何时止损转型，何时该继续迭代。\",\"priority\":\"P0\",\"fit_score\":95,\"question_type\":\"风险管理 | 交易心理\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"反复亏损的币圈散户\",\"凭感觉交易的短线客\",\"陷入情绪内耗的交易者\"],\"pain_points\":[\"凭感觉开单，缺乏明确入场和出场规则\",\"亏损后急于回本导致动作变形\",\"分不清是市场周期问题还是策略本身失效\",\"用真金白银试错，心理和资金双重受压\"],\"recommended_angle\":\"以“止损盲目坚持，坚持科学验证”为核心。先回答“什么情况下必须停手，什么情况下可以优化继续”，再给出具体可操作的复盘、验证和风控框架。自然引入“先验证再交易”的理念，将情绪化亏损转化为数据化迭代。\",\"persona_hooks\":[\"二牛早期凭直觉交易反复吃亏损的经历\",\"从“死扛回本”到“规则验证”的认知转变\",\"强调用历史数据代替主观臆测的实战价值\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"问题直击“一直赔”的痛点，核心解法是停止盲目试错、转向策略验证与规则复盘。这正好对应 CryptoPathX 的核心主张“先验证，再交易”和可视化回测功能，可作为将主观想法转化为可验证流程的自然工具承接点。\",\"should_include_soft_promo\":true,\"soft_promo_directive\":{\"should_include\":true,\"mode\":\"natural\",\"reason\":\"适合在讨论如何验证策略有效性和降低真金白银试错成本时自然植入\",\"product_anchor\":\"可视化回测与AI辅助策略验证流程\",\"writer_instruction\":\"这篇需要自然加入 CryptoPathX。在给出停止凭感觉试错、转向历史数据验证的段落时，提及可用 CryptoPathX 这类工具把交易逻辑拆成明确条件跑回测，看胜率、最大回撤和盈亏比，而不是盲目用本金试错。保持克制具体，放在验证流程节点，禁止写成广告或喊单。\"},\"writing_plan\":{\"length_mode\":\"long\",\"target_words_min\":2200,\"target_words_max\":3500,\"structure_mode\":\"痛点破局 + 亏损归因（动作变形与周期错配） + 典型案例复盘 + 验证路径（回测与规则化） + 风控底线与收口 + case action chain\",\"should_use_cases\":true,\"case_style\":\"typical_composite\",\"should_include_calculation\":true,\"should_include_list\":true,\"should_use_bold\":true,\"bold_targets\":[\"核心结论：停盲目坚持，坚持验证\",\"亏损动作变形清单\",\"回测与风控算账结论\",\"策略失效边界\",\"core judgment\",\"risk boundary\"],\"suggested_sections\":[\"开头直接给判断\",\"持续亏损的三种典型陷阱\",\"复合案例：情绪交易与动作变形\",\"如何把主观经验转成可验证规则\",\"算账：真金白银试错的成本\",\"何时该停，何时该继续\",\"克制收口\",\"concrete case\",\"action chain\",\"review takeaway\"],\"writer_notes\":\"保持克制客观，不承诺回本或稳赚。案例需包含市场背景、入场逻辑、仓位设定、心态变化和复盘结论。算账部分要贴近币圈真实手续费和滑点常识。产品植入必须放在降低试错门槛、用数据验证想法的环节。案例数字保守自洽，不要精确伪造历史数据。\\nCase-driven default: for crypto/trading topics, make at least one concrete case carry the core argument. Prefer source/user-provided cases or backend case_research when available; otherwise use a realistic composite case with price/time path, entry trigger, position or budget, long/short temptation, stop-loss/action deformation, outcome pressure, and review takeaway. Do not keep reusing the same token, story arc, or reference wording across different answers.\"},\"must_avoid\":[\"承诺回本或稳定盈利\",\"推荐具体币种或交易所\",\"夸大AI预测能力或暗示自动跟单\",\"将软广写成产品说明书或硬广\",\"给出绝对化的财务建议\"],\"risk_notes\":[\"明确回测历史表现不代表未来收益，需警惕过度拟合\",\"强调本文为经验分享与复盘思路，不构成投资建议\",\"注意情绪安抚但不兜底，保持客观风险提示\"],\"topic_fingerprint\":{\"problem_core\":\"持续亏损下的交易决策困境与心理内耗\",\"answer_angle\":\"从情绪化坚持转向数据化验证，明确止损与迭代边界\",\"target_pain\":\"凭感觉交易导致反复试错、资金与心理双重受压\",\"promo_entry\":\"策略验证与历史回测工作流\"}},\"prefilterCachedAt\":\"2026-04-27T10:19:07.322Z\"}', 'P0', 95, '风险管理 | 交易心理', '二牛经验型', '[\"承诺回本或稳定盈利\",\"推荐具体币种或交易所\",\"夸大AI预测能力或暗示自动跟单\",\"将软广写成产品说明书或硬广\",\"给出绝对化的财务建议\"]', '[\"明确回测历史表现不代表未来收益，需警惕过度拟合\",\"强调本文为经验分享与复盘思路，不构成投资建议\",\"注意情绪安抚但不兜底，保持客观风险提示\"]', 'unchecked', NULL, NULL, 'accepted', '{\"problem_core\":\"持续亏损下的交易决策困境与心理内耗\",\"answer_angle\":\"从情绪化坚持转向数据化验证，明确止损与迭代边界\",\"target_pain\":\"凭感觉交易导致反复试错、资金与心理双重受压\",\"promo_entry\":\"策略验证与历史回测工作流\"}', '2026-04-27 18:17:30');
INSERT INTO `topic_cards` VALUES (11, 48, '从实战角度拆解“预测”的局限性与“分类”的实用性。结合币圈震荡行情，说明为何依赖预测容易爆仓，而基于分类的交易系统更稳健。自然引入工具辅助验证分类策略的有效性，强调纪律与风控。', '{\"validity_status\":\"valid\",\"validity_reason\":\"高度契合交易类选题，探讨预测与分类的本质，可自然引入风险管理、策略验证逻辑，适合承接 CryptoPathX 的回测与纪律功能。\",\"title\":\"投资里别总想着预测，做好“完全分类”才能活过震荡期\",\"summary\":\"从实战角度拆解“预测”的局限性与“分类”的实用性。结合币圈震荡行情，说明为何依赖预测容易爆仓，而基于分类的交易系统更稳健。自然引入工具辅助验证分类策略的有效性，强调纪律与风控。\",\"priority\":\"P1\",\"fit_score\":85,\"question_type\":\"方法验证\",\"persona_mode\":\"二牛经验型\",\"target_audience\":[\"亏损散户\",\"交易体系构建者\"],\"pain_points\":[\"盲目预测行情\",\"缺乏风控体系\",\"震荡期亏损\"],\"recommended_angle\":\"用实战亏损经验反推分类思想的重要性，弱化理论，强调执行。\",\"persona_hooks\":[\"曾经迷信预测的亏钱经历\",\"转向分类后的稳定心态\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"可自然展示如何用工具验证分类策略的胜率与盈亏比\",\"must_avoid\":[\"绝对化承诺收益\",\"贬低其他交易流派\"],\"risk_notes\":[\"避免涉及具体币种推荐\"],\"topic_fingerprint\":{\"problem_core\":\"交易哲学与风控\",\"answer_angle\":\"实战经验复盘\",\"target_pain\":\"预测失败导致亏损\",\"promo_entry\":\"策略分类验证与回测\"}}', '2026-03-26 15:56:25');
INSERT INTO `topic_cards` VALUES (12, 83, '不谈暴富神话，只谈生存法则。针对小白最容易忽视的资金管理和风险识别误区，结合历史行情数据做拆解。强调在入场前用工具验证过往走势，建立自己的风险边界和交易纪律。比起听信大 V 建议或盲目跟单，用数据说话更能避免成为韭菜。适合想长期生存而非赌一把的初学者阅读。', '{\"validity_status\":\"valid\",\"validity_reason\":\"痛点最清晰（避免踩坑），天然契合产品的风险管理和历史走势验证能力。用户意图是寻求保护而非单纯求代码，适合用焦花花务实人设，通过数据回测展示如何识别风险，自然植入产品。\",\"title\":\"币圈小白想进场？先搞懂这 3 个“不死”原则再谈赚钱\",\"summary\":\"不谈暴富神话，只谈生存法则。针对小白最容易忽视的资金管理和风险识别误区，结合历史行情数据做拆解。强调在入场前用工具验证过往走势，建立自己的风险边界和交易纪律。比起听信大 V 建议或盲目跟单，用数据说话更能避免成为韭菜。适合想长期生存而非赌一把的初学者阅读。\",\"priority\":\"P0\",\"fit_score\":90,\"question_type\":\"风险管理\",\"persona_mode\":\"焦花花实测型\",\"target_audience\":[\"币圈小白\",\"风险厌恶型投资者\",\"想学习交易纪律的人\"],\"pain_points\":[\"怕踩坑\",\"怕亏光本金\",\"不知道如何验证信息\"],\"recommended_angle\":\"以风险控制为核心，引入历史数据验证作为避坑手段\",\"persona_hooks\":[\"用数据说话\",\"不吹牛只讲生存\",\"强调纪律\"],\"soft_promo_mode\":\"natural\",\"soft_promo_reason\":\"产品核心能力（历史走势对比、风险验证）直接解决“如何避免踩坑”的问题，植入逻辑顺畅。\",\"must_avoid\":[\"推荐具体交易所\",\"承诺收益\",\"鼓励杠杆\",\"制造焦虑\"],\"risk_notes\":[\"合规风险\",\"避免被误解为投资建议\",\"数据准确性说明\"],\"topic_fingerprint\":{\"problem_core\":\"新手风险防控\",\"answer_angle\":\"数据验证 + 风控纪律\",\"target_pain\":\"害怕亏损和被骗\",\"promo_entry\":\"用工具回测历史风险场景\"}}', '2026-03-26 16:00:33');
INSERT INTO `topic_cards` VALUES (13, 67, '聚焦交易生涯中的迟来认知，如止损纪律、不重仓赌方向等。结合焦花花真实经历，表达若有早期验证工具可避免部分损失。适合建立信任感与专业度。', '{\"title\":\"你人生中太晚明白的道理是什么？\",\"summary\":\"聚焦交易生涯中的迟来认知，如止损纪律、不重仓赌方向等。结合焦花花真实经历，表达若有早期验证工具可避免部分损失。适合建立信任感与专业度。\",\"priority\":\"P2\",\"fit_score\":75,\"question_type\":\"入门认知\",\"persona_mode\":\"焦花花踩坑型\",\"target_audience\":[\"交易亏损者\",\"反思型交易者\",\"新手\"],\"pain_points\":[\"后悔没早止损\",\"凭感觉交易\",\"缺乏复盘工具\"],\"recommended_angle\":\"情感共鸣 + 干货教训，结尾落脚到工具辅助决策的价值。\",\"persona_hooks\":[\"真金白银换来的教训\",\"不回避过往失误\",\"务实复盘\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"作为教训总结后的改进方案提及，不喧宾夺主。\",\"must_avoid\":[\"过度卖惨\",\"具体金额炫耀\",\"保证以后不亏\"],\"risk_notes\":[\"避免具体币种推荐\",\"保持理性基调\"],\"topic_fingerprint\":{\"problem_core\":\"交易认知滞后\",\"answer_angle\":\"经验教训总结\",\"target_pain\":\"重复犯错\",\"promo_entry\":\"辅助验证与复盘工具\"}}', '2026-03-26 16:56:10');
INSERT INTO `topic_cards` VALUES (14, 57, '针对新手的生存指南。重点讨论资金安全、防骗意识、情绪管理和仓位控制。强调不要杠杆，不要借贷，用历史数据辅助判断而非听消息。', '{\"title\":\"刚入币圈需要注意些什么？老实话：保住本金比赚钱更重要\",\"summary\":\"针对新手的生存指南。重点讨论资金安全、防骗意识、情绪管理和仓位控制。强调不要杠杆，不要借贷，用历史数据辅助判断而非听消息。\",\"priority\":\"P1\",\"fit_score\":88,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"刚入金的新手\",\"有过小额亏损经历的用户\"],\"pain_points\":[\"怕资金不安全\",\"怕操作失误\",\"不知道风险在哪\"],\"recommended_angle\":\"以\'生存\'为核心，列举具体风险场景，并给出应对策略（如复盘、验证）。\",\"persona_hooks\":[\"分享自己早期忽视风险的经历\",\"强调老实做人，踏实做事\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在提到\'复盘\'和\'验证历史走势\'时，可轻描淡写提及工具辅助。\",\"must_avoid\":[\"推荐实盘平台\",\"鼓励高频交易\",\"夸大风险可控性\"],\"risk_notes\":[\"合规风险，避免指导具体操作\",\"避免引发焦虑\"],\"topic_fingerprint\":{\"problem_core\":\"新手生存风险\",\"answer_angle\":\"风控第一，交易第二\",\"target_pain\":\"本金损失\",\"promo_entry\":\"复盘与风险验证工具\"}}', '2026-03-26 17:10:28');
INSERT INTO `topic_cards` VALUES (15, 57, '针对新手的生存指南。重点讨论资金安全、防骗意识、情绪管理和仓位控制。强调不要杠杆，不要借贷，用历史数据辅助判断而非听消息。', '{\"title\":\"刚入币圈需要注意些什么？老实话：保住本金比赚钱更重要\",\"summary\":\"针对新手的生存指南。重点讨论资金安全、防骗意识、情绪管理和仓位控制。强调不要杠杆，不要借贷，用历史数据辅助判断而非听消息。\",\"priority\":\"P1\",\"fit_score\":88,\"question_type\":\"风险管理\",\"persona_mode\":\"二牛踩坑型\",\"target_audience\":[\"刚入金的新手\",\"有过小额亏损经历的用户\"],\"pain_points\":[\"怕资金不安全\",\"怕操作失误\",\"不知道风险在哪\"],\"recommended_angle\":\"以\'生存\'为核心，列举具体风险场景，并给出应对策略（如复盘、验证）。\",\"persona_hooks\":[\"分享自己早期忽视风险的经历\",\"强调老实做人，踏实做事\"],\"soft_promo_mode\":\"light\",\"soft_promo_reason\":\"在提到\'复盘\'和\'验证历史走势\'时，可轻描淡写提及工具辅助。\",\"must_avoid\":[\"推荐实盘平台\",\"鼓励高频交易\",\"夸大风险可控性\"],\"risk_notes\":[\"合规风险，避免指导具体操作\",\"避免引发焦虑\"],\"topic_fingerprint\":{\"problem_core\":\"新手生存风险\",\"answer_angle\":\"风控第一，交易第二\",\"target_pain\":\"本金损失\",\"promo_entry\":\"复盘与风险验证工具\"}}', '2026-03-26 17:46:06');
