INSERT INTO `x_hotspot_sources` VALUES (22, 25, '552e43ae5e35357af6a256a01989cf748d51c033e1b4e46bcf4b80b7bbea8194', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/what-happened-in-crypto-today?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound', 'Here’s what happened in crypto today', 'Need to know what happened in crypto today? Here is the latest news on daily trends and events impacting Bitcoin price, blockchain, DeFi, NFTs, Web3 and crypto regulation.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Here’s what happened in crypto today\",\"link\":\"https://cointelegraph.com/news/what-happened-in-crypto-today?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Need to know what happened in crypto today? Here is the latest news on daily trends and events impacting Bitcoin price, blockchain, DeFi, NFTs, Web3 and crypto regulation.\",\"publishedAt\":\"2026-04-05T21:46:22.000Z\"}', '2026-04-05 21:46:22', '2026-04-06 08:26:06', 15, '2026-04-06 16:26:06');
INSERT INTO `x_hotspot_sources` VALUES (44, 25, '458fdcffb7b7b6a296418457927b742cb8094814715ed6148bd855a589886b72', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/what-happened-in-crypto-today', 'Here’s what happened in crypto today', 'Need to know what happened in crypto today? Here is the latest news on daily trends and events impacting Bitcoin price, blockchain, DeFi, NFTs, Web3 and crypto regulation.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Here’s what happened in crypto today\",\"link\":\"https://cointelegraph.com/news/what-happened-in-crypto-today?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Need to know what happened in crypto today? Here is the latest news on daily trends and events impacting Bitcoin price, blockchain, DeFi, NFTs, Web3 and crypto regulation.\",\"publishedAt\":\"2026-04-05T21:46:22.000Z\"}', '2026-04-05 21:46:22', '2026-04-06 08:28:07', 15, '2026-04-06 16:28:07');
INSERT INTO `x_hotspot_sources` VALUES (234, 225, 'cedb62ba1944831640715908286f1dd80d912e765191decc11a2b6b7c8388da4', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/bitcoin-could-be-quantum-safe', 'Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims', 'Bitcoin Magazine Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims Bitcoin transactions could be resistant to quantum attacks without changing the network’s core rules, a new proposal contends. This post Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims\",\"link\":\"https://bitcoinmagazine.com/news/bitcoin-could-be-quantum-safe\",\"summary\":\"Bitcoin Magazine Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims Bitcoin transactions could be resistant to quantum attacks without changing the network’s core rules, a new proposal contends. This post Bitcoin Could Be Quantum-Safe Without Protocol Changes, New Proposal Claims first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-09T20:56:54.000Z\"}', '2026-04-09 20:56:54', '2026-04-09 21:28:04', 15, '2026-04-10 05:28:04');
INSERT INTO `x_hotspot_sources` VALUES (235, 226, '4c5ea2cf3c6a4607c4bd76e86be46b8029e76bb2735ed35e12b32514f5bb330a', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/strategys-bitcoin-ambition-is-reshaping', 'Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind', 'Bitcoin Magazine Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind Michael Saylor’s Strategy is driving nearly all corporate Bitcoin accumulation, turning its STRC-fueled treasury model into the dominant force reshaping how companies approach Bitcoin in 2026. This post Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind\",\"link\":\"https://bitcoinmagazine.com/news/strategys-bitcoin-ambition-is-reshaping\",\"summary\":\"Bitcoin Magazine Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind Michael Saylor’s Strategy is driving nearly all corporate Bitcoin accumulation, turning its STRC-fueled treasury model into the dominant force reshaping how companies approach Bitcoin in 2026. This post Strategy’s (MSTR) Bitcoin Ambition Is Reshaping Corporate Finance. Everyone Else Is Falling Behind first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-09T19:42:20.000Z\"}', '2026-04-09 19:42:20', '2026-04-09 21:28:04', 30, '2026-04-10 05:28:04');
INSERT INTO `x_hotspot_sources` VALUES (236, 227, '40d8a71ca7e59890dc7552dd160519e43deb52d7e5538a9cd2e7ddf105f70912', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/business/stacked-formerly-lightning-pay-launches-self-custodial-lightning-wallet-as-new-zealands-last-major-non-custodial-bitcoin-exchange', 'Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange', 'Bitcoin Magazine Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange Stacked, the rebranded Lightning Pay, has emerged as one of the few remaining non-custodial Bitcoin platforms in New Zealand after a wave of mergers and shutdowns. The company today launched a self-custodial Lightning wallet built on Breez and Spark SDKs, enabling users to receive Bitcoin directly into their own wallets and pay utility bills or rent via Open Banking. This post Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange first appeared on Bitcoin Magazine and is written by Juan Galt .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange\",\"link\":\"https://bitcoinmagazine.com/business/stacked-formerly-lightning-pay-launches-self-custodial-lightning-wallet-as-new-zealands-last-major-non-custodial-bitcoin-exchange\",\"summary\":\"Bitcoin Magazine Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange Stacked, the rebranded Lightning Pay, has emerged as one of the few remaining non-custodial Bitcoin platforms in New Zealand after a wave of mergers and shutdowns. The company today launched a self-custodial Lightning wallet built on Breez and Spark SDKs, enabling users to receive Bitcoin directly into their own wallets and pay utility bills or rent via Open Banking. This post Stacked (formerly Lightning Pay) launches self-custodial Lightning wallet as New Zealand’s last major non-custodial Bitcoin exchange first appeared on Bitcoin Magazine and is written by Juan Galt .\",\"publishedAt\":\"2026-04-09T19:23:37.000Z\"}', '2026-04-09 19:23:37', '2026-04-09 21:28:04', 10, '2026-04-10 05:28:04');
