INSERT INTO `x_hotspot_sources` VALUES (262, 253, 'b66bf9357a5aacab3532589a91e8179f71d5990a6f374773f52935bcb7532c82', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/ether-machine-spac-ethm-cancelled-dynamix-merger', 'Ether Machine scraps SPAC merger with Dynamix, citing market conditions', 'The Ethereum treasury firm aimed to launch a $1.5 billion yield-bearing ETH fund but will now halt its plans following the mutual decision to end the deal.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Ether Machine scraps SPAC merger with Dynamix, citing market conditions\",\"link\":\"https://cointelegraph.com/news/ether-machine-spac-ethm-cancelled-dynamix-merger?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"The Ethereum treasury firm aimed to launch a $1.5 billion yield-bearing ETH fund but will now halt its plans following the mutual decision to end the deal.\",\"publishedAt\":\"2026-04-12T07:37:14.000Z\"}', '2026-04-12 07:37:14', '2026-04-12 08:56:43', 27, '2026-04-12 16:56:43');
INSERT INTO `x_hotspot_sources` VALUES (263, 254, 'b7cedb9f2ab504655cb2786ea6496bd61670b87640341e82ec0f2dce3324d8b8', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/bitcoin-ether-crypto-market-trend-reversal-macro-investor', 'Bitcoin, Ether near levels that could signal trend reversal: Analyst', 'Bitcoin and Ether are each less than 10% away from price levels that could signal a potential reversal in the crypto market, according to a macro analyst.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Bitcoin, Ether near levels that could signal trend reversal: Analyst\",\"link\":\"https://cointelegraph.com/news/bitcoin-ether-crypto-market-trend-reversal-macro-investor?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Bitcoin and Ether are each less than 10% away from price levels that could signal a potential reversal in the crypto market, according to a macro analyst.\",\"publishedAt\":\"2026-04-12T05:26:55.000Z\"}', '2026-04-12 05:26:55', '2026-04-12 08:56:43', 17, '2026-04-12 16:56:43');
INSERT INTO `x_hotspot_sources` VALUES (264, 255, '076eb4670c7399b760da0c11f37851101034c56ce7d3b6dd5b50bbf45834e8f4', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/trump-backlash-crypto-tokens-crash', 'US President Trump faces renewed backlash as Trump-linked tokens crash', 'Democratic lawmakers and crypto investors characterized crypto projects launched by or tied to Trump as scams and political corruption.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"US President Trump faces renewed backlash as Trump-linked tokens crash\",\"link\":\"https://cointelegraph.com/news/trump-backlash-crypto-tokens-crash?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Democratic lawmakers and crypto investors characterized crypto projects launched by or tied to Trump as scams and political corruption.\",\"publishedAt\":\"2026-04-11T21:40:02.000Z\"}', '2026-04-11 21:40:02', '2026-04-12 08:56:43', 0, '2026-04-12 16:56:43');
INSERT INTO `x_hotspot_sources` VALUES (265, 256, '90472ecfe598cdb67d7b4fb525bd011c82055b0e04bf31d3b67c8fc16d4d5243', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/crypto-crashed-six-months-ago-have-markets-improved-or-are-bears-still-in-charge', 'Crypto crashed six months ago: Have markets improved, or are bears still in charge?', 'The October 2025 Bitcoin and altcoin crash may have ended the bull market, but its long-term impact on market health may have been overstated.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Crypto crashed six months ago: Have markets improved, or are bears still in charge?\",\"link\":\"https://cointelegraph.com/news/crypto-crashed-six-months-ago-have-markets-improved-or-are-bears-still-in-charge?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"The October 2025 Bitcoin and altcoin crash may have ended the bull market, but its long-term impact on market health may have been overstated.\",\"publishedAt\":\"2026-04-11T19:33:32.000Z\"}', '2026-04-11 19:33:32', '2026-04-12 08:56:43', 5, '2026-04-12 16:56:43');
INSERT INTO `x_hotspot_sources` VALUES (266, 257, '522e86667f4ebce2c6be528458983998cdf0ba662b420138d1c18a1acddd1ca8', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/bitcoin-price-analysis-sees-new-short-squeeze-as-open-interest-nears-25b', 'Bitcoin price analysis sees new short squeeze as open interest nears $25B', 'Bitcoin open interest hit five-week highs while funding rates mimicked the BTC price collapse below $60,000, leading analysis to predict a new short squeeze.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Bitcoin price analysis sees new short squeeze as open interest nears $25B\",\"link\":\"https://cointelegraph.com/news/bitcoin-price-analysis-sees-new-short-squeeze-as-open-interest-nears-25b?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Bitcoin open interest hit five-week highs while funding rates mimicked the BTC price collapse below $60,000, leading analysis to predict a new short squeeze.\",\"publishedAt\":\"2026-04-11T18:28:22.000Z\"}', '2026-04-11 18:28:22', '2026-04-12 08:56:43', 13, '2026-04-12 16:56:43');
INSERT INTO `x_hotspot_sources` VALUES (267, 258, 'a3ad8c973b9238ded26bf0d5c26478d8f62785e9f7f41a6e924ce6b3c9ef988d', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/messaging-notifications-privacy-attack-durov', 'Messaging push notifications are a privacy attack surface, says Durov', 'The comments followed recent reports that law enforcement officials retrieved deleted Signal messages through device push notification logs.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Messaging push notifications are a privacy attack surface, says Durov\",\"link\":\"https://cointelegraph.com/news/messaging-notifications-privacy-attack-durov?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"The comments followed recent reports that law enforcement officials retrieved deleted Signal messages through device push notification logs.\",\"publishedAt\":\"2026-04-11T17:57:57.000Z\"}', '2026-04-11 17:57:57', '2026-04-12 08:56:43', 0, '2026-04-12 16:56:43');
