INSERT INTO `x_hotspot_sources` VALUES (281, 272, '98f845a8d3acd2b422ec813e1750593bec1dda99d32b23433b212d563b030a2f', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/print/the-core-issue-the-role-and-history-of-bitcoin-core-maintainers', 'The Core Issue: The Role and History of Bitcoin Core Maintainers', 'Bitcoin Magazine The Core Issue: The Role and History of Bitcoin Core Maintainers Bitcoin Core’s maintainer system began with Satoshi Nakamoto merging every commit himself. Today, trusted key holders like Ava Chow, Gloria Zhao and the newly added TheCharlatan control merges to the master branch—ensuring the $2T+ network’s stability through merit-based consensus. This post The Core Issue: The Role and History of Bitcoin Core Maintainers first appeared on Bitcoin Magazine and is written by Juan Galt .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"The Core Issue: The Role and History of Bitcoin Core Maintainers\",\"link\":\"https://bitcoinmagazine.com/print/the-core-issue-the-role-and-history-of-bitcoin-core-maintainers\",\"summary\":\"Bitcoin Magazine The Core Issue: The Role and History of Bitcoin Core Maintainers Bitcoin Core’s maintainer system began with Satoshi Nakamoto merging every commit himself. Today, trusted key holders like Ava Chow, Gloria Zhao and the newly added TheCharlatan control merges to the master branch—ensuring the $2T+ network’s stability through merit-based consensus. This post The Core Issue: The Role and History of Bitcoin Core Maintainers first appeared on Bitcoin Magazine and is written by Juan Galt .\",\"publishedAt\":\"2026-04-11T13:00:00.000Z\"}', '2026-04-11 13:00:00', '2026-04-12 08:56:44', 20, '2026-04-12 16:56:44');
INSERT INTO `x_hotspot_sources` VALUES (282, 273, '35e6a4e38177d607f1b0a85469364307fda2e5a1d754690affeb6e4fe843244c', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/bitcoin-policy-institute-warns-of-quantum', 'Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades', 'Bitcoin Magazine Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades A new brief from the Bitcoin Policy Institute says advances in quantum computing may bring forward risks to Bitcoin’s cryptography, though developers are already working on fixes. This post Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades\",\"link\":\"https://bitcoinmagazine.com/news/bitcoin-policy-institute-warns-of-quantum\",\"summary\":\"Bitcoin Magazine Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades A new brief from the Bitcoin Policy Institute says advances in quantum computing may bring forward risks to Bitcoin’s cryptography, though developers are already working on fixes. This post Bitcoin Policy Institute Warns Quantum Advances Are Compressing Timeline for Network Upgrades first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-10T20:01:16.000Z\"}', '2026-04-10 20:01:16', '2026-04-12 08:56:44', 0, '2026-04-12 16:56:44');
INSERT INTO `x_hotspot_sources` VALUES (283, 274, '1e4b5d157af9ce73b79e84b65f215c4cf9ba360dbc762377e6bf6cd25f257644', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/blackrock-massive-bitcoin-etf-inflows', 'BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand', 'Bitcoin Magazine BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand U.S. spot Bitcoin ETFs saw a $358.1 million inflow surge led by BlackRock’s IBIT, while Morgan Stanley’s new MSBT debuted with strong early demand This post BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand\",\"link\":\"https://bitcoinmagazine.com/news/blackrock-massive-bitcoin-etf-inflows\",\"summary\":\"Bitcoin Magazine BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand U.S. spot Bitcoin ETFs saw a $358.1 million inflow surge led by BlackRock’s IBIT, while Morgan Stanley’s new MSBT debuted with strong early demand This post BlackRock Posts Massive Bitcoin ETF Inflows as Morgan Stanley Debuts MSBT With Strong Early Demand first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-10T18:35:54.000Z\"}', '2026-04-10 18:35:54', '2026-04-12 08:56:44', 23, '2026-04-12 16:56:44');
INSERT INTO `x_hotspot_sources` VALUES (284, 275, 'dfd19750cf11df01347227636f6463dc5aa42015709dee0a581dd154d0c02b97', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/td-cowen-initiates-coverage-on-bitcoin', 'TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category', 'Bitcoin Magazine TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category TD Cowen initiated coverage on three public Bitcoin treasury firms. The firm also predicted that bitcoin will hit roughly $140,000 this year. This post TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category\",\"link\":\"https://bitcoinmagazine.com/news/td-cowen-initiates-coverage-on-bitcoin\",\"summary\":\"Bitcoin Magazine TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category TD Cowen initiated coverage on three public Bitcoin treasury firms. The firm also predicted that bitcoin will hit roughly $140,000 this year. This post TD Cowen Initiates Coverage on Bitcoin Treasury Companies, Frames PBTC Sector as Investable Equity Category first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-10T18:32:06.000Z\"}', '2026-04-10 18:32:06', '2026-04-12 08:56:44', 32, '2026-04-12 16:56:44');
INSERT INTO `x_hotspot_sources` VALUES (285, 276, '03624276167b8d8bf91e231ea8bb1c2830e8b4c5e7f83038c97aee5a10689232', 'news', 'Bitcoin Magazine RSS', 'https://bitcoinmagazine.com/news/japan-moves-to-classify-bitcoin-and-crypto', 'Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill', 'Bitcoin Magazine Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill Japan plans to reclassify cryptocurrencies as financial products under the Financial Instruments and Exchange Act, shifting them from a payment-based framework to one aligned with traditional securities regulation. This post Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill first appeared on Bitcoin Magazine and is written by Micah Zimmerman .', '{\"sourceLabel\":\"Bitcoin Magazine RSS\",\"title\":\"Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill\",\"link\":\"https://bitcoinmagazine.com/news/japan-moves-to-classify-bitcoin-and-crypto\",\"summary\":\"Bitcoin Magazine Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill Japan plans to reclassify cryptocurrencies as financial products under the Financial Instruments and Exchange Act, shifting them from a payment-based framework to one aligned with traditional securities regulation. This post Japan Moves to Classify Bitcoin and Crypto as Financial Instruments Under New Bill first appeared on Bitcoin Magazine and is written by Micah Zimmerman .\",\"publishedAt\":\"2026-04-10T14:14:45.000Z\"}', '2026-04-10 14:14:45', '2026-04-12 08:56:44', 10, '2026-04-12 16:56:44');
