INSERT INTO `x_hotspot_sources` VALUES (288, 279, 'bab209f59131fa21eae384fdbcdcc76eb6324666b660d7b9a6cc0dbefb9bb4fe', 'watchlist', '@lookonchain', 'https://x.com/lookonchain/status/2043150096242737531', '@lookonchain Machi(@machibigbrother)\'s 13-win streak has been broken. Due to the market crash, he just clo...', 'Machi(@machibigbrother)\'s 13-win streak has been broken.\n\nDue to the market crash, he just closed his $BTC long, taking a $192K loss.\nThings seem to be getting better.\n\nMachi(@machibigbrother) hasn\'t been liquidated for 10 days and has now won 13 trades in a row, making $1.14M profit over the past week.\n\nhttps://legacy.hyperdash.com/trader/0x020cA66C30beC2c4Fe3861a94E4DB4A498A35872…', '{\"watchlistItemId\":1,\"watchlistItemValue\":\"@lookonchain\",\"watchlistLabel\":\"lookonchain\",\"collectorAccountId\":\"b92e1be8-dc61-4918-b238-c82c644bd20a\",\"handle\":\"lookonchain\",\"tweet\":{\"tweetUrl\":\"https://x.com/lookonchain/status/2043150096242737531\",\"text\":\"Machi(@machibigbrother)\'s 13-win streak has been broken.\\n\\nDue to the market crash, he just closed his $BTC long, taking a $192K loss.\\nThings seem to be getting better.\\n\\nMachi(@machibigbrother) hasn\'t been liquidated for 10 days and has now won 13 trades in a row, making $1.14M profit over the past week.\\n\\nhttps://legacy.hyperdash.com/trader/0x020cA66C30beC2c4Fe3861a94E4DB4A498A35872…\",\"publishedAt\":\"2026-04-12T02:11:57.000Z\"}}', '2026-04-12 02:11:57', '2026-04-12 08:56:52', 72, '2026-04-12 16:56:52');
