INSERT INTO `x_hotspot_sources` VALUES (334, 325, '2b01a9b169e181e7f59012f821dc28b7785e219627c2b0f260e7585384a53544', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/former-cftc-chair-giancarlo-leaves-law-focus-on-crypto-advisory', 'Former CFTC chair Giancarlo leaves law to focus on crypto advisory', 'Chris Giancarlo, who oversaw the first Bitcoin futures ETF approval as CFTC chairman, will now advise fintech and digital asset founders and boards.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Former CFTC chair Giancarlo leaves law to focus on crypto advisory\",\"link\":\"https://cointelegraph.com/news/former-cftc-chair-giancarlo-leaves-law-focus-on-crypto-advisory?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Chris Giancarlo, who oversaw the first Bitcoin futures ETF approval as CFTC chairman, will now advise fintech and digital asset founders and boards.\",\"publishedAt\":\"2026-04-14T03:23:58.000Z\"}', '2026-04-14 03:23:58', '2026-04-14 07:16:52', 27, '2026-04-14 15:16:52');
