INSERT INTO `x_hotspot_sources` VALUES (336, 327, '7c3066e20103bad3773fa895c2efa6b5575f5eda3972e757db4ebcfea37ff72a', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/south-korea-coinone-suspension-aml-fine', 'South Korea fines Coinone $3.5M, orders partial business suspension: Reports', 'Coinone is the second to face South Korea’s crackdown on exchanges in the last month, following a $24 million fine and a six-month partial suspension order against Bithumb.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"South Korea fines Coinone $3.5M, orders partial business suspension: Reports\",\"link\":\"https://cointelegraph.com/news/south-korea-coinone-suspension-aml-fine?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Coinone is the second to face South Korea’s crackdown on exchanges in the last month, following a $24 million fine and a six-month partial suspension order against Bithumb.\",\"publishedAt\":\"2026-04-14T03:05:55.000Z\"}', '2026-04-14 03:05:55', '2026-04-14 07:16:52', 25, '2026-04-14 15:16:52');
