INSERT INTO `x_hotspot_sources` VALUES (338, 329, 'b7254c08769563ff74fc37d08a0edb88d8937e5baa34a469ec5854f10ea6626f', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/ether-holders-back-in-profit-as-eth-price-aims-for-rally-to-dollar3k', 'Ether holders back in profit as ETH price aims for rally to $3K', 'Large Ether investors are back in profit, increasing the chances of a rally toward $3,000, but resistance at $2,800 may delay the recovery.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Ether holders back in profit as ETH price aims for rally to $3K\",\"link\":\"https://cointelegraph.com/news/ether-holders-back-in-profit-as-eth-price-aims-for-rally-to-dollar3k?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Large Ether investors are back in profit, increasing the chances of a rally toward $3,000, but resistance at $2,800 may delay the recovery.\",\"publishedAt\":\"2026-04-14T00:14:43.000Z\"}', '2026-04-14 00:14:43', '2026-04-14 07:16:52', 32, '2026-04-14 15:16:52');
INSERT INTO `x_hotspot_sources` VALUES (339, 330, '09eefa8bcac49c6ac40eebcdb9b132236b4bad841051c12d35fede58d90f261b', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/bitcoin-reclaims-dollar74k-as-spot-etf-demand-clashes-with-btc-miner-sell-pressure', 'Bitcoin reclaims $74K as spot ETF demand clashes with BTC miner sell pressure', 'Bitcoin rallied above $74,000 after the Monday stock market close, but derivatives data show that some traders remain bearish.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Bitcoin reclaims $74K as spot ETF demand clashes with BTC miner sell pressure\",\"link\":\"https://cointelegraph.com/news/bitcoin-reclaims-dollar74k-as-spot-etf-demand-clashes-with-btc-miner-sell-pressure?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"Bitcoin rallied above $74,000 after the Monday stock market close, but derivatives data show that some traders remain bearish.\",\"publishedAt\":\"2026-04-13T22:48:42.000Z\"}', '2026-04-13 22:48:42', '2026-04-14 07:16:52', 50, '2026-04-14 15:16:52');
INSERT INTO `x_hotspot_sources` VALUES (340, 331, 'afc7ad95c366be554e7270cb1e4857d59cb2a116875edf8a21fd600ddf160b1b', 'news', 'Cointelegraph RSS', 'https://cointelegraph.com/news/broadridge-rolls-out-crypto-tokenized-asset-platform-for-canada-wealth-managers', 'Broadridge rolls out crypto, tokenized asset platform for Canada wealth managers', 'The technology services provider said wealth managers have faced challenges integrating digital assets without relying on separate systems.', '{\"sourceLabel\":\"Cointelegraph RSS\",\"title\":\"Broadridge rolls out crypto, tokenized asset platform for Canada wealth managers\",\"link\":\"https://cointelegraph.com/news/broadridge-rolls-out-crypto-tokenized-asset-platform-for-canada-wealth-managers?utm_source=rss_feed&utm_medium=rss&utm_campaign=rss_partner_inbound\",\"summary\":\"The technology services provider said wealth managers have faced challenges integrating digital assets without relying on separate systems.\",\"publishedAt\":\"2026-04-13T21:51:59.000Z\"}', '2026-04-13 21:51:59', '2026-04-14 07:16:52', 10, '2026-04-14 15:16:52');
