INSERT INTO `x_hotspots` VALUES (253, 'news:7ab1a3062a700f99d87e0da9b07083cb9a08c5427f9ddaf30d912a91f3c29f80', 'Ether Machine scraps SPAC merger with Dynamix, citing market conditions', 'The Ethereum treasury firm aimed to launch a $1.5 billion yield-bearing ETH fund but will now halt its plans following the mutual decision to end the deal.', 'news', 'news_flash', '[\"ETH\"]', '[\"ETH\",\"AI\"]', '[]', 'https://cointelegraph.com/news/ether-machine-spac-ethm-cancelled-dynamix-merger', 27, 'DROP', 'active', 'not_needed', 1, '2026-04-12 07:37:14', '2026-04-12 09:22:19', '2026-04-12 07:37:14', '2026-04-15 09:22:19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-12 16:56:43', '2026-04-12 17:22:19');
