INSERT INTO `x_hotspots` VALUES (288, 'news:255a5d1e890b906c5bde45d178e85f8ceab3604d43d3418540a1e70322716dd3', '消息人士：万斯的离开不过是展示实力的作秀，美伊谈判将继续进行', 'BlockBeats 消息，4 月 12 日，据消息人士透露，美伊谈判将继续进行，而万斯的离开不过是展示实力的一场作秀。 此外，伊朗议会议长称：伊朗代表团提出了具有前瞻性的倡议，但对方在本轮谈判中最终未能赢得伊朗代表团的信任。美国已经理解了伊朗的逻辑和原则，现在是他们决定能否赢得我们信任的时候了。 今日早前，美伊谈判结束，双方未达成协议，谈判结束后美国副总统万斯离开巴基斯坦，伊朗代表团也将于 12 日离开。美伊下一轮谈判的时间、地点及计划目前尚未公布。', 'news', 'news_flash', '[]', '[]', '[]', 'https://m.theblockbeats.info/flash/340760', 5, 'DROP', 'active', 'not_needed', 1, '2026-04-12 09:03:33', '2026-04-12 09:22:19', '2026-04-12 09:03:33', '2026-04-15 09:22:19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-12 17:03:31', '2026-04-12 17:22:19');
