INSERT INTO `x_hotspots` VALUES (290, 'news:6b5f7c374ffd089b55f16917b00ddce4325c4f9c16a30de38f8d8af7a6bc1fe7', '「狂飙」山寨币RAVE近4日拉升超10倍，某地址浮盈超5000万美元', 'BlockBeats 消息，4 月 12 日，据 HTX 行情信息，「狂飙」山寨币之一的 RAVE 近 24 小时涨幅 56%，现报 2.78 美元，一度触及 3.17 美元，4 月 8 日以来自 0.26 美元大幅拉升超 10 倍。 据链上分析师 Ai 姨（@ai_9684xtpa）监测，过去两天累计从 Bitget 提出 3193 万枚 RAVE 的多签地址 0x0A1...790d7，其资产价值已从 3754 万美元飙涨至 8910 万美元，两日增加约 5 千万美元。而 4 月 8 日时，这部分代币还仅价值 852 万美元。', 'news', 'market_event', '[]', '[\"AI\"]', '[]', 'https://m.theblockbeats.info/flash/340761', 15, 'DROP', 'active', 'not_needed', 1, '2026-04-12 09:19:06', '2026-04-12 09:22:19', '2026-04-12 09:19:06', '2026-04-15 09:22:19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-12 17:20:31', '2026-04-12 17:22:19');
